import { motion } from "framer-motion";
import { SafeImage } from "@/components/ui/safe-image";

type Props = {
  title: string;
  category: string;
  location?: string;
  src: string;
  onClick: () => void;
};

export default function GalleryCard({ title, category, location, src, onClick }: Props) {
  return (
    <motion.button
      type="button"
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.99 }}
      onClick={onClick}
      className="group relative w-full overflow-hidden rounded-2xl border bg-card text-card-foreground shadow-sm"
    >
      <div className="aspect-[4/3]">
        <SafeImage src={src} alt={title} className="h-full w-full object-cover" />
      </div>
      <div className="pointer-events-none absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors" />
      <div className="absolute bottom-0 left-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
        <div className="rounded-xl bg-black/60 p-3 text-white">
          <p className="text-sm font-semibold leading-tight">{title}</p>
          <p className="text-xs opacity-90">{category}{location ? ` • ${location}` : ""}</p>
        </div>
      </div>
    </motion.button>
  );
}


