const allCompletedTags: CompletedTag[] = ['School Installation', 'Private Home', 'Resort', 'Community Park', 'Custom Design'];

const CompletedProjects = () => {
  const [activeTag, setActiveTag] = useState<CompletedTag | 'All'>('All');
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [lightboxProject, setLightboxProject] = useState<CompletedProject | null>(null);
  const [coverLoaded, setCoverLoaded] = useState<Record<number, boolean>>({});
  const prefersReduced = useReducedMotion();

  const filtered = useMemo(
    () => (activeTag === 'All' ? completedData : completedData.filter((p) => p.tags.includes(activeTag))),
    [activeTag]
  );

  const containerVariants = {
    hidden: { opacity: 0 },
    show: { opacity: 1, transition: { staggerChildren: 0.06 } },
  } as const;
  const itemVariants = {
    hidden: { opacity: 0, y: 12 },
    show: { opacity: 1, y: 0, transition: { type: 'spring', stiffness: 120, damping: 18 } },
  } as const;

  return (
    <section id="completed-projects" aria-label="Completed jungle gym installation projects in Botswana" className="py-20 bg-white">
      <div className="container mx-auto px-4">
        <div className="text-center mb-8">
          <h2 className="text-3xl md:text-4xl font-extrabold text-gray-800 tracking-tight">Completed Projects</h2>
          <p className="text-muted-foreground mt-2">Recently completed playground construction across Botswana.</p>
        </div>

        <div className="flex flex-col items-center gap-3 mb-8">
          <div className="flex flex-wrap justify-center gap-2">
            <Button onClick={() => setActiveTag('All')} variant={activeTag === 'All' ? 'default' : 'outline'} className="rounded-full">All</Button>
            {allCompletedTags.map((tag) => (
              <Button key={tag} onClick={() => setActiveTag(tag)} variant={activeTag === tag ? 'default' : 'outline'} className="rounded-full">{tag}</Button>
            ))}
          </div>
        </div>

        <motion.div
          variants={containerVariants}
          initial={prefersReduced ? false : 'hidden'}
          animate={prefersReduced ? undefined : 'show'}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
        >
          {filtered.map((project) => (
            <motion.div key={project.id} variants={itemVariants} whileHover={prefersReduced ? undefined : { scale: 1.01 }}>
              <Card className="group rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 flex flex-col border-gray-200 will-change-transform">
                <CardContent className="p-0">
                  <div className="relative">
                    {!coverLoaded[project.id] && (
                      <Skeleton className="absolute inset-0 h-56 md:h-64 lg:h-72 rounded-t-2xl" />
                    )}
                    <Carousel className="w-full rounded-t-2xl" opts={{ loop: true }}>
                      <CarouselContent>
                        {project.images.map((src, idx) => (
                          <CarouselItem key={idx}>
                            <img
                              src={src}
                              alt={`${project.name} finished image ${idx + 1}`}
                              className="w-full h-56 md:h-64 lg:h-72 object-cover"
                              loading="lazy"
                              onLoad={() => setCoverLoaded((m) => ({ ...m, [project.id]: true }))}
                            />
                          </CarouselItem>
                        ))}
                      </CarouselContent>
                      {project.images.length > 1 && <><CarouselPrevious className="left-2" /><CarouselNext className="right-2" /></>}
                    </Carousel>
                  </div>
                </CardContent>

                <div className="p-6 flex-grow flex flex-col">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xl font-bold text-gray-900 leading-tight line-clamp-2">{project.name}</h3>
                    <Badge className="bg-blue-600 text-white">Completed</Badge>
                  </div>
                  <div className="flex items-center text-sm text-gray-500 mb-3">
                    <MapPin className="w-4 h-4 mr-2" />
                    <span>{project.location}</span>
                  </div>
                  <p className="text-gray-700 text-sm mb-4 line-clamp-3">{project.description}</p>

                  <div className="flex items-center justify-between mt-auto">
                    <div className="inline-flex items-center gap-2">
                      <CalendarCheck2 className="w-4 h-4 text-gray-500" />
                      <span className="text-sm text-gray-600">Completed: {project.completedAt}</span>
                    </div>
                    <Badge className="bg-green-600 text-white">Revenue: {formatCurrency(project.revenueBWP, 'BWP')}</Badge>
                  </div>

                  <div className="flex flex-wrap gap-2 mt-4">
                    {project.tags.map((tag) => (
                      <Badge key={tag} variant="secondary">{tag}</Badge>
                    ))}
                  </div>
                </div>

                <CardFooter className="p-4 bg-gray-50 rounded-b-2xl">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 w-full">
                    <Button
                      className="w-full bg-gradient-to-r from-blue-500 to-indigo-600 hover:from-blue-600 hover:to-indigo-700 shadow-md hover:shadow-lg transition-all"
                      onClick={() => { setLightboxProject(project); setIsLightboxOpen(true); }}
                    >
                      View Project
                    </Button>
                    <Button asChild variant="outline" className="w-full border-2 hover:shadow-sm">
                      <a href={`/contact?project_inquiry=${encodeURIComponent(project.name)}`} aria-label={`Get a quote similar to ${project.name}`}>Get a Quote</a>
                    </Button>
                  </div>
                </CardFooter>
              </Card>
            </motion.div>
          ))}
        </motion.div>
      </div>

      {/* Lightbox Modal */}
      <Dialog open={isLightboxOpen} onOpenChange={setIsLightboxOpen}>
        <DialogContent className="max-w-5xl">
          {lightboxProject && (
            <>
              <DialogHeader>
                <DialogTitle>{lightboxProject.name}</DialogTitle>
                <DialogDescription>{lightboxProject.location}</DialogDescription>
              </DialogHeader>
              <Carousel className="w-full rounded-md" opts={{ loop: true }}>
                <CarouselContent>
                  {lightboxProject.images.map((src, idx) => (
                    <CarouselItem key={idx}>
                      <img src={src} alt={`${lightboxProject.name} image ${idx + 1}`} className="w-full h-[60vh] object-contain bg-black" />
                    </CarouselItem>
                  ))}
                </CarouselContent>
                {lightboxProject.images.length > 1 && <><CarouselPrevious className="left-2" /><CarouselNext className="right-2" /></>}
              </Carousel>
              <div className="mt-3 text-sm text-muted-foreground">{lightboxProject.description}</div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </section>
  );
};

export default CompletedProjects;


