export async function fetchZARToBWPRate(): Promise<number> {
  try {
    const res = await fetch('https://api.exchangerate.host/latest?base=ZAR&symbols=BWP');
    if (!res.ok) throw new Error('Rate fetch failed');
    const data = await res.json();
    const rate = data?.rates?.BWP;
    if (typeof rate === 'number' && rate > 0) return rate;
    return 0.76; // sane fallback
  } catch (e) {
    console.warn('Falling back to static rate 0.76 due to error:', e);
    return 0.76;
  }
}

export function formatCurrency(amount: number, currency: 'BWP' | 'ZAR', locale: string = currency === 'BWP' ? 'en-BW' : 'en-ZA') {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
  }).format(amount);
}
