import { useEffect, useMemo, useState } from 'react';
import { Card, CardContent, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { useCart } from '@/contexts/CartContext';
import { formatCurrency } from '@/utils/currency';
import { Carousel, CarouselContent, CarouselItem, CarouselNext, CarouselPrevious } from '@/components/ui/carousel';
import { getEffectivePrice, isEditingEnabled, removeOverride, setOverride } from '@/utils/priceOverrides';

interface ImportedProduct {
  id: string;
  name: string;
  description: string;
  image: string;
  images?: string[];
  fullDescription?: string;
  productInfo?: string[];
  category: string;
  price: number; // BWP
  originalZARPrice: number; // ZAR
  inStock: boolean;
  availabilityText?: string;
  link: string;
  shippingNotes: string;
  shippingTag?: string;
}

export const ImportedProductsSection = ({
  filterCategory,
  title = 'Kids Playground Gear (Botswana)'
}: {
  filterCategory?: string;
  title?: string;
}) => {
  const [items, setItems] = useState<ImportedProduct[]>([]);
  const [editedPriceInputs, setEditedPriceInputs] = useState<Record<string, string>>({});
  const { addItem } = useCart();

  useEffect(() => {
    try {
      const raw = localStorage.getItem('jungle-city-imported-products');
      if (raw) {
        const parsed = JSON.parse(raw) as ImportedProduct[];
        setItems(parsed);
      }
    } catch (e) {
      console.warn('Failed to load imported products');
    }
  }, []);

  useEffect(() => {
    const initial: Record<string, string> = {};
    items.forEach((p) => {
      const price = getEffectivePrice(p.id, p.price);
      initial[p.id] = String(price);
    });
    setEditedPriceInputs(initial);
  }, [items]);

  const resolvedItems = useMemo(() => {
    return items.map((p) => ({ ...p, price: getEffectivePrice(p.id, p.price) }));
  }, [items]);

  const visibleItems = filterCategory
    ? resolvedItems.filter((p) => p.category === filterCategory)
    : resolvedItems;

  if (!visibleItems.length) return null;

  return (
    <section className="py-12">
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-foreground">{title}</h2>
          <Badge className="bg-jungle">Imported</Badge>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {visibleItems.map((p) => (
            <Card key={p.id} className="overflow-hidden border-2 border-border/50">
              <div className="relative">
                {p.images && p.images.length > 1 ? (
                  <div className="p-4">
                    <Carousel className="w-full">
                      <CarouselContent>
                        {p.images.map((src, idx) => (
                          <CarouselItem key={idx} className="basis-full">
                            <img src={src} alt={`${p.name} image ${idx + 1}`} className="w-full h-64 object-cover rounded" loading="lazy" />
                          </CarouselItem>
                        ))}
                      </CarouselContent>
                      <CarouselPrevious />
                      <CarouselNext />
                    </Carousel>
                  </div>
                ) : (
                  <img src={p.image} alt={`${p.name} playground product`} className="w-full h-64 object-cover" loading="lazy" />
                )}
                <Badge className="absolute top-2 left-2 bg-jungle">{p.category}</Badge>
              </div>
              <CardContent className="p-4">
                <h3 className="font-semibold line-clamp-2">
                  <a href={p.link} target="_blank" rel="noopener noreferrer" className="underline text-jungle hover:text-jungle/80">
                    {p.name}
                  </a>
                </h3>
                <div className="text-sm text-muted-foreground mt-2 whitespace-pre-line">
                  {(p.fullDescription || p.description || '').trim()}
                </div>
                {p.productInfo && p.productInfo.length > 0 && (
                  <ul className="mt-3 list-disc list-inside text-sm text-foreground/90 space-y-1">
                    {p.productInfo.slice(0, 6).map((line, idx) => (
                      <li key={idx}>{line}</li>
                    ))}
                  </ul>
                )}
                <div className="text-sm mt-2">
                  {formatCurrency(p.originalZARPrice, 'ZAR')} (
                  approx. {formatCurrency(p.price, 'BWP')})
                </div>
                {isEditingEnabled() && (
                  <div className="mt-3 grid grid-cols-3 gap-2">
                    <input
                      type="number"
                      min={0}
                      value={editedPriceInputs[p.id] ?? ''}
                      onChange={(e) => setEditedPriceInputs((prev) => ({ ...prev, [p.id]: e.target.value }))}
                      className="col-span-2 border rounded px-2 py-1 text-sm"
                      placeholder="Enter BWP price"
                    />
                    <Button
                      size="sm"
                      className="bg-jungle hover:bg-jungle/90"
                      onClick={() => {
                        const next = Number(editedPriceInputs[p.id]);
                        if (Number.isFinite(next) && next > 0) {
                          setOverride(p.id, next);
                          setEditedPriceInputs((prev) => ({ ...prev, [p.id]: String(Math.round(next)) }));
                          setItems((prev) => prev.map((it) => (it.id === p.id ? { ...it } : it)));
                        }
                      }}
                    >
                      Save
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        removeOverride(p.id);
                        setEditedPriceInputs((prev) => ({ ...prev, [p.id]: String(getEffectivePrice(p.id, p.price)) }));
                        setItems((prev) => prev.map((it) => (it.id === p.id ? { ...it } : it)));
                      }}
                    >
                      Reset
                    </Button>
                  </div>
                )}
                <div className="flex items-center gap-2 mt-2">
                  <Badge className={p.inStock ? 'bg-grass' : 'bg-safety'}>{p.availabilityText || (p.inStock ? 'In stock' : 'Out of stock')}</Badge>
                  <Badge variant="outline">{p.shippingTag || 'Unknown'}</Badge>
                  <span className="text-xs text-muted-foreground">{p.shippingNotes}</span>
                </div>
              </CardContent>
              <CardFooter className="p-4 pt-0 grid grid-cols-2 gap-2">
                <Button 
                  className="bg-playground hover:bg-playground/90"
                  onClick={() => addItem({ id: p.id, name: p.name, price: p.price, image: p.image, category: p.category })}
                >
                  Add to Cart
                </Button>
                <a href={p.link} target="_blank" rel="noopener noreferrer" className="w-full">
                  <Button variant="outline" className="w-full">View on Takealot</Button>
                </a>
              </CardFooter>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
