import { useEffect, useMemo, useState } from 'react';
import { FirecrawlService } from '@/utils/FirecrawlService';
import { useToast } from '@/hooks/use-toast';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { formatCurrency, fetchZARToBWPRate } from '@/utils/currency';

interface ImportedProduct {
  id: string;
  name: string;
  description: string;
  image: string;
  images?: string[];
  fullDescription?: string;
  productInfo?: string[];
  category: string;
  price: number; // BWP
  originalZARPrice: number; // ZAR
  inStock: boolean;
  availabilityText?: string;
  link: string; // Original product link
  shippingNotes: string;
  shippingTag?: string; // e.g., 'SA Only' | 'International' | 'Unknown'
}

const DEFAULT_URL = 'https://www.takealot.com/all?_sb=1&_r=1&_si=f766ba194090641a586148d6db74cb97&qsearch=kids%20Outdoor%20Toys%20%26%20Play%20Accessories';

function guessCategory(name: string): string {
  const n = name.toLowerCase();
  if (/(indoor).*?(toy|accessor|accessories)/.test(n)) return 'Indoor Toys & Play Accessories';
  if (/(outdoor).*?(toy|accessor|accessories)/.test(n)) return 'Indoor Toys & Play Accessories';
  if (/(recycled|polywood|composite|hdpe).*?(jungle|gym|play|frame)/.test(n) || /(plastic).*?(wood)/.test(n)) return 'Recycled Plastic Wood Jungle Gyms';
  if (/(jungle|gym|dome|monkey|climb)/.test(n)) return 'Jungle Gyms';
  if (/(swing|slide|glide)/.test(n)) return 'Swings & Slides';
  if (/(frame|holds|wall)/.test(n)) return 'Climbing Frames';
  if (/(educational|chair|table|mat|ball pit|pit|sand|sandbox)/.test(n)) return 'Educational Outdoor Toys';
  if (/(wood|house|playhouse)/.test(n)) return 'Wooden Playhouses';
  return 'Swings & Slides';
}

function toId(text: string) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 50);
}

export const TakealotImporter = () => {
  const { toast } = useToast();
  const [url, setUrl] = useState(DEFAULT_URL);
  const [apiKey, setApiKey] = useState(FirecrawlService.getApiKey() || '');
  const [isLoading, setIsLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [rate, setRate] = useState(0.76);
  const [results, setResults] = useState<ImportedProduct[]>([]);

  useEffect(() => {
    fetchZARToBWPRate().then(setRate).catch(() => setRate(0.76));
  }, []);

  const convertedPreview = useMemo(() => rate, [rate]);

  const handleSaveKey = async () => {
    if (!apiKey.trim()) return;
    FirecrawlService.saveApiKey(apiKey.trim());
    const ok = await FirecrawlService.testApiKey(apiKey.trim());
    toast({ title: ok ? 'API Key Saved' : 'API Key Invalid', description: ok ? 'Ready to import products.' : 'Please check your key and try again.', variant: ok ? 'default' : 'destructive' });
  };

  // Import using Takealot JSON API (requires CORS to succeed). If blocked, advise using crawler.
  const handleApiImport = async () => {
    try {
      setIsLoading(true);
      setProgress(10);
      const apiUrl =
        url.includes('api.takealot.com')
          ? url
          : 'https://api.takealot.com/rest/v-1-14-0/searches/products,filters,facets,sort_options,breadcrumbs,slots_audience,context,seo,layout?r=1&sb=1&si=f766ba194090641a586148d6db74cb97&qsearch=kids+Outdoor+Toys+%26+Play+Accessories&searchbox=true';

      // Attempt direct fetch (may fail due to CORS when run in browser)
      const resp = await fetch(apiUrl, { headers: { accept: 'application/json' } });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data: any = await resp.json();
      setProgress(50);

      const results = (data?.sections?.products?.results as any[]) || [];
      if (!results.length) throw new Error('No products found in API response');

      const items: ImportedProduct[] = [];
      for (const r of results.slice(0, 20)) {
        const name: string = (r?.title || '').toString().trim();
        if (!name) continue;
        const id = toId(name);
        // Images: try common fields
        const imgCandidates: string[] = [
          ...(Array.isArray(r?.images) ? r.images.map((i: any) => i?.url || i?.src || '') : []),
          ...(Array.isArray(r?.product_images) ? r.product_images.map((i: any) => i?.url || i?.src || '') : []),
          r?.image_url || '',
        ].filter((s: any) => typeof s === 'string' && s.startsWith('http'));
        const images = Array.from(new Set(imgCandidates)).slice(0, 4);
        const image = images[0] || 'https://via.placeholder.com/600x400?text=Outdoor+Toy';

        // Description
        const description: string = (r?.short_description || r?.description || name).toString().trim();

        // Link
        const link: string = (r?.url || r?.product_url || '').toString();

        // Price (ZAR). Handle cents if necessary.
        let zarRaw = Number(
          r?.price ?? r?.buying_options?.[0]?.price ?? r?.purchase_options?.[0]?.price ?? 0
        );
        if (Number.isNaN(zarRaw) || zarRaw <= 0) continue;
        if (zarRaw > 10000) zarRaw = Math.round(zarRaw / 100); // assume cents
        const baseBwp = Math.round(zarRaw * rate);
        const priceWithProfit = Math.round(baseBwp * 2.0); // 100% profit

        items.push({
          id,
          name,
          description,
          image,
          images,
          fullDescription: description,
          productInfo: undefined,
          category: 'Indoor Toys & Play Accessories',
          price: priceWithProfit,
          originalZARPrice: zarRaw,
          inStock: true,
          availabilityText: 'In stock',
          link,
          shippingNotes: 'Check shipping options; Botswana delivery not guaranteed',
          shippingTag: 'Unknown',
        });
      }

      if (!items.length) throw new Error('No items mapped from API response');

      // Initial save with basic data
      setResults(items);
      localStorage.setItem('jungle-city-imported-products', JSON.stringify(items));
      setProgress(80);
      toast({ title: 'Phase 1 Complete', description: `Fetched ${items.length} products. Now enriching with details...` });

      // Phase 2: Enrich with details using Firecrawl
      if (FirecrawlService.getApiKey()) {
        for (const item of items) {
          if (!item.link) continue;
          try {
            const detail = await FirecrawlService.crawlWebsite(item.link, {
              pageOptions: { onlyMainContent: true }
            });
            if (detail.success) {
              const detailData = (detail.data as any)?.data?.[0];
              if (detailData?.markdown) {
                item.fullDescription = detailData.markdown;
              }
              if (detailData?.metadata?.sourceURL) {
                const detailDoc = new DOMParser().parseFromString((detailData as any)?.html || '', 'text/html');
                const gallery = Array.from(new Set(Array.from(detailDoc.querySelectorAll('img')).map(img => img.src).filter(src => src && /takealot|media\./i.test(src))));
                if (gallery.length > 1) {
                  item.images = gallery.slice(0, 4);
                  item.image = item.images[0] || item.image;
                }
              }
            }
          } catch (e) { /* Ignore individual enrichment errors */ }
        }
        setResults([...items]);
        localStorage.setItem('jungle-city-imported-products', JSON.stringify(items));
        toast({ title: 'Enrichment Complete', description: 'All products updated with detailed info.' });
      } else {
        toast({ title: 'Enrichment Skipped', description: 'Firecrawl API key not set. Skipping detailed import.', variant: 'default' });
      }

      setProgress(100);
    } catch (e: any) {
      console.error(e);
      toast({
        title: 'API import failed',
        description: e?.message || 'CORS blocked. Use the crawler import instead.',
        variant: 'destructive',
      });
      setProgress(0);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCrawl = async () => {
    if (!FirecrawlService.getApiKey()) {
      toast({ title: 'API key required', description: 'Enter and save your Firecrawl API key first.', variant: 'destructive' });
      return;
    }
    setIsLoading(true);
    setProgress(10);
    try {
      const res = await FirecrawlService.crawlWebsite(url);
      setProgress(60);
      if (!res.success) throw new Error(res.error || 'Crawl failed');

      // Expecting res.data to contain an array with html; use first page
      const html = (res.data?.data?.[0]?.html || res.data?.data?.[0]?.content || '') as string;
      if (!html) throw new Error('No HTML content returned');

      const doc = new DOMParser().parseFromString(html, 'text/html');
      const items: ImportedProduct[] = [];

      // Domain-specific: greenfurniture.co.za recycled plastic jungle gyms
      try {
        const host = new URL(url).host;
        if (/greenfurniture\.co\.za/i.test(host)) {
          const tiles = Array.from(doc.querySelectorAll('section, article, li, div'))
            .filter((el) => {
              const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
              return /Price\s*R|Add to Cart|Select Delivery/i.test(t) && el.querySelector('img');
            })
            .slice(0, 60);

          const seen = new Set<string>();
          for (const el of tiles) {
            const imgEl = (el.querySelector('img') as HTMLImageElement) || undefined;
            const image = imgEl?.src || imgEl?.getAttribute('data-src') || '';
            if (!image) continue;

            // Name: prefer heading text or alt text
            const heading = (el.querySelector('h3, h4, strong, .title, .name') as HTMLElement) || undefined;
            let name = (heading?.textContent || imgEl?.alt || '').replace(/\s+/g, ' ').trim();
            if (!name) {
              // Fallback to nearest preceding heading
              const prev = el.previousElementSibling as HTMLElement | null;
              name = (prev?.textContent || '').trim();
            }
            if (!name) name = 'Recycled Plastic Jungle Gym';
            const id = toId(name);
            if (seen.has(id)) continue;
            seen.add(id);

            // Price (ZAR) e.g., "PriceR2,900.00" or "R 2,900"
            const t = (el.textContent || '').replace(/\s+/g, ' ');
            const priceMatch = t.match(/R\s*([0-9][0-9\s,.]+)/i);
            const zarRaw = priceMatch ? Number(priceMatch[1].replace(/[^0-9]/g, '')) : NaN;

            // Description: short text nearby
            const descNode = (el.querySelector('p, .description, .subtitle') as HTMLElement) || undefined;
            const description = (descNode?.textContent || 'Eco-friendly recycled plastic jungle gym built for durability and low maintenance.').trim();

            // Link (if any)
            const linkEl = (el.querySelector('a') as HTMLAnchorElement) || undefined;
            let link = linkEl?.href || url;
            if (link && link.startsWith('/')) link = `https://${host}${link}`;

            let originalZARPrice = 0;
            let price = 0;
            if (zarRaw && Number.isFinite(zarRaw)) {
              originalZARPrice = zarRaw;
              const baseBwp = Math.round(zarRaw * convertedPreview);
              price = Math.round(baseBwp * 2.0);
            }

            items.push({
              id,
              name,
              description,
              image,
              images: [image],
              fullDescription: description,
              productInfo: [
                'Made from recycled plastic (polywood)',
                'Weather and UV resistant',
                'Low maintenance • Easy to clean',
              ],
              category: 'Recycled Plastic Wood Jungle Gyms',
              price,
              originalZARPrice,
              inStock: true,
              availabilityText: 'Made to order',
              link,
              shippingNotes: 'Custom manufacture • Botswana delivery on request',
              shippingTag: 'Custom',
            });
          }
        }
      } catch {}

      // Heuristic selectors for Takealot product tiles
      const productNodes = items.length
        ? []
        : Array.from(doc.querySelectorAll('a, article, div'))
            .filter((el) => /product|tile|card/i.test(el.className || ''))
            .slice(0, 250);

      const seen = new Set<string>();
      for (const el of productNodes) {
        // Name
        const titleEl = (el.querySelector('[data-ref="product-name"], h4, h3, .title, .name') as HTMLElement) || undefined;
        const name = titleEl?.textContent?.trim();
        if (!name || name.length < 5) continue;

        // Image
        const imgEl = (el.querySelector('img') as HTMLImageElement) || undefined;
        const image = imgEl?.src || imgEl?.getAttribute('data-src') || '';
        if (!image) continue;

        // Price (ZAR)
        const priceText = (el.textContent || '').match(/R\s?([0-9][0-9\s,]+)/i)?.[1] || '';
        const zar = priceText ? Number(priceText.replace(/[^0-9]/g, '')) : NaN;
        if (!zar || !Number.isFinite(zar)) continue;

        // Description
        const descEl = (el.querySelector('.subtitle, .sub-title, p, .description') as HTMLElement) || undefined;
        const description = (descEl?.textContent || name || 'Outdoor toy').trim();

        const id = toId(name);
        if (seen.has(id)) continue;
        seen.add(id);

        // Link
        const linkEl = (el.closest('a') as HTMLAnchorElement) || (el.querySelector('a') as HTMLAnchorElement) || undefined;
        let link = linkEl?.href || '';
        if (link && link.startsWith('/')) link = `https://www.takealot.com${link}`;

        // Shipping suitability heuristic (listing pages rarely expose explicit BW shipping info)
        const textContent = (el.textContent || '').toLowerCase();
        let shippingTag: string = 'Unknown';
        if (/imported|international/.test(textContent)) shippingTag = 'International';
        else if (/sold by takealot|takealot/.test(textContent)) shippingTag = 'SA Only';
        const shippingNotes =
          shippingTag === 'International'
            ? 'Likely international/marketplace; may require forwarding to Botswana'
            : shippingTag === 'SA Only'
            ? 'Ships within South Africa; forwarding needed for Botswana'
            : 'Check shipping options; Botswana delivery not guaranteed';

        const baseBwp = Math.round(zar * convertedPreview);
        const priceWithProfit = Math.round(baseBwp * 2.0); // 100% profit margin
        const inferredCategory = guessCategory(name);
        const forcedOutdoor = /outdoor%20toys%20%26%20play%20accessories/i.test(url) || /Outdoor\s+Toys\s*&\s*Play\s*Accessories/i.test(url);
        items.push({
          id,
          name,
          description,
          image: image || 'https://via.placeholder.com/600x400?text=Outdoor+Toy',
          category: forcedOutdoor ? 'Indoor Toys & Play Accessories' : inferredCategory,
          originalZARPrice: zar,
          price: priceWithProfit,
          inStock: true,
          availabilityText: 'In stock',
          link,
          shippingNotes,
          shippingTag,
        });
        if (items.length >= 40) break;
      }

      // Domain-specific fallback for Green Plastic Wood (no pricing, info-only)
      if (!items.length && /greenplasticwood\.co\.za/.test(new URL(url).host)) {
        const pageText = (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
        const uniqImg = Array.from(new Set(Array.from(doc.querySelectorAll('img'))
          .map((im) => (im as HTMLImageElement).src || (im as HTMLImageElement).getAttribute('data-src') || '')
          .filter((s) => typeof s === 'string' && s.includes('/wp-') && s.startsWith('http'))
        ));

        const infoBullets: string[] = [];
        const bulletCandidates = Array.from(doc.querySelectorAll('li')).map((li) => (li.textContent || '').trim()).filter(Boolean);
        infoBullets.push(...bulletCandidates.slice(0, 12));

        const baseDesc = pageText.slice(0, 600);
        const groupSize = 4;
        const groups = Math.min(6, Math.ceil(uniqImg.length / groupSize) || 1);
        for (let i = 0; i < groups; i++) {
          const imgs = uniqImg.slice(i * groupSize, i * groupSize + groupSize);
          if (!imgs.length) continue;
          const name = `Recycled Plastic Wood Jungle Gym #${i + 1}`;
          const id = toId(`${name}-${i}`);
          items.push({
            id,
            name,
            description: baseDesc,
            image: imgs[0],
            images: imgs,
            fullDescription: baseDesc,
            productInfo: Array.from(new Set(infoBullets)).slice(0, 8),
            category: 'Recycled Plastic Wood Jungle Gyms',
            originalZARPrice: 0,
            price: 0,
            inStock: true,
            availabilityText: 'Made to order',
            link: url,
            shippingNotes: 'Custom build • Request a quote',
            shippingTag: 'Custom',
          });
        }
      }

      if (!items.length) throw new Error('No products parsed. Adjust selectors or try again.');

      // Enrich each product with detail page info: 3-4 images, full description, product information, stock status
      let completed = 0;
      for (const item of items) {
        try {
          if (!item.link) {
            completed += 1;
            setProgress(60 + Math.round((completed / items.length) * 30));
            continue;
          }
          const detail = await FirecrawlService.crawlWebsite(item.link);
          if (detail.success) {
            const detailHtml = (detail.data as any)?.data?.[0]?.html || (detail.data as any)?.data?.[0]?.content || '';
            if (detailHtml) {
              const detailDoc = new DOMParser().parseFromString(detailHtml, 'text/html');

              // Images (limit to 4)
              const imgNodes = Array.from(detailDoc.querySelectorAll('img')) as HTMLImageElement[];
              const gallery = Array.from(new Set(
                imgNodes
                  .map((img) => img.src || img.getAttribute('data-src') || '')
                  .filter((src) => typeof src === 'string' && src && /takealot|media\./i.test(src))
              ));
              if (gallery.length) {
                item.images = gallery.slice(0, 4);
                item.image = item.images[0] || item.image;
              }

              // Full Description
              const candidates: Element[] = Array.from(
                detailDoc.querySelectorAll('#product-content, #product-details, section, article, .content, .product-content, .description, [data-ref="product-content"]')
              );
              let bestText = '';
              for (const c of candidates) {
                const text = (c.textContent || '').trim();
                if (text.length > bestText.length) bestText = text;
              }
              if (bestText && bestText.length > (item.description?.length || 0)) {
                item.fullDescription = bestText;
              }

              // Product Information / Specs
              const infoBullets: string[] = [];
              const infoHeadings = Array.from(detailDoc.querySelectorAll('h2, h3'))
                .filter((h) => /product information|specification|specifications|details/i.test((h.textContent || '').toLowerCase()));
              for (const heading of infoHeadings) {
                const next = heading.nextElementSibling;
                if (next && next.tagName.toLowerCase() === 'ul') {
                  const lis = Array.from(next.querySelectorAll('li')).map((li) => (li.textContent || '').trim()).filter(Boolean);
                  infoBullets.push(...lis);
                }
                const table = next && next.tagName.toLowerCase() === 'table' ? next : null;
                if (table) {
                  const rows = Array.from(table.querySelectorAll('tr'));
                  infoBullets.push(
                    ...rows.map((tr) => {
                      const cells = Array.from(tr.querySelectorAll('th,td')).map((c) => (c.textContent || '').trim()).filter(Boolean);
                      return cells.length >= 2 ? `${cells[0]}: ${cells[1]}` : cells.join(' ');
                    }).filter(Boolean)
                  );
                }
              }
              if (infoBullets.length < 3) {
                const bullets = Array.from(detailDoc.querySelectorAll('.description ul li, .product-content ul li'))
                  .slice(0, 6)
                  .map((li) => (li.textContent || '').trim())
                  .filter(Boolean);
                infoBullets.push(...bullets);
              }
              if (infoBullets.length) {
                item.productInfo = Array.from(new Set(infoBullets)).slice(0, 8);
              }

              // Availability / stock
              const availabilityText = (detailDoc.body.textContent || '').toLowerCase();
              if (/out of stock|sold out|unavailable/.test(availabilityText)) {
                item.inStock = false;
                item.availabilityText = 'Out of stock';
              } else if (/in stock|available to buy|ready to ship/.test(availabilityText)) {
                item.inStock = true;
                item.availabilityText = 'In stock';
              }
            }
          }
        } catch (e) {
          // ignore errors per item
        } finally {
          completed += 1;
          setProgress(60 + Math.round((completed / items.length) * 30));
        }
      }

      setResults(items);
      setProgress(95);

      // Persist to localStorage for store consumption
      localStorage.setItem('jungle-city-imported-products', JSON.stringify(items));

      toast({ title: 'Imported!', description: `${items.length} products saved with images and details. Open /store to see them.` });
      setProgress(100);
    } catch (e: any) {
      console.error(e);
      toast({ title: 'Import failed', description: e?.message || 'Please try again', variant: 'destructive' });
      setProgress(0);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="container mx-auto max-w-3xl p-6">
      <Card>
        <CardHeader>
          <CardTitle>Takealot Product Importer</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-2">
            <label className="text-sm">Firecrawl API Key</label>
            <div className="flex gap-2">
              <Input type="password" value={apiKey} onChange={(e) => setApiKey(e.target.value)} placeholder="Enter your Firecrawl API key" />
              <Button onClick={handleSaveKey} className="bg-jungle hover:bg-jungle/90">Save Key</Button>
            </div>
          </div>

          <div className="grid gap-2">
            <label className="text-sm">Takealot Search URL</label>
            <Input value={url} onChange={(e) => setUrl(e.target.value)} />
          </div>

          <div className="text-sm text-muted-foreground">
            Live ZAR→BWP rate: <Badge variant="secondary">{rate.toFixed(2)} BWP</Badge>
          </div>

          {isLoading && <Progress value={progress} />}

          <div className="flex flex-col sm:flex-row gap-2">
            <Button disabled={isLoading} onClick={handleCrawl} className="bg-playground hover:bg-playground/90">
              {isLoading ? 'Importing…' : 'Import via Crawler (recommended)'}
            </Button>
            <Button disabled={isLoading} variant="outline" onClick={handleApiImport}>
              {isLoading ? 'Importing…' : 'Import via Takealot API (beta)'}
            </Button>
          </div>

          {results.length > 0 && (
            <div className="mt-6 grid gap-4">
              {results.map((p) => (
                <div key={p.id} className="flex gap-4 items-center border rounded-lg p-3">
                  <img src={p.image} alt={`${p.name} playground product`} className="w-16 h-16 object-cover rounded" />
                  <div className="flex-1">
                    <div className="font-medium">
                      <a href={p.link} target="_blank" rel="noopener noreferrer" className="underline text-jungle hover:text-jungle/80">
                        {p.name}
                      </a>
                    </div>
                    <div className="text-xs text-muted-foreground line-clamp-2">{p.description}</div>
                    <div className="text-sm mt-1">
                      {formatCurrency(p.originalZARPrice, 'ZAR')} (
                      approx. {formatCurrency(p.price, 'BWP')})
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                      <Badge variant="outline">{p.shippingTag || 'Unknown'}</Badge>
                      <span className="text-xs text-muted-foreground">{p.shippingNotes}</span>
                    </div>
                  </div>
                  <Badge className="bg-jungle">{p.category}</Badge>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};
