// --- DATA STRUCTURES ---
type ProjectStatus = 'Planning' | 'In Progress' | 'Finalizing' | 'Completed';
type ProjectTag = 'School Installation' | 'Private Home' | 'Resort' | 'Community Park' | 'Custom Design';

interface Project {
  id: number;
  name: string;
  location: string;
  status: ProjectStatus;
  progress: number; // Percentage 0-100
  eta: string; // e.g., "August 2025"
  description: string;
  tags: ProjectTag[];
  images: string[]; // For the carousel
  videos?: string[]; // Optional looping videos
  beforeAfter?: boolean; // Optional before/after hover effect if at least two images
}

