const allTags: ProjectTag[] = ['School Installation', 'Private Home', 'Resort', 'Community Park', 'Custom Design'];

// --- COMPONENT ---
const OngoingProjects = () => {
  const [activeTag, setActiveTag] = useState<ProjectTag | 'All'>('All');

  const filteredProjects = activeTag === 'All' 
    ? projectsData 
    : projectsData.filter(p => p.tags.includes(activeTag));

  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case 'In Progress': return 'bg-blue-500';
      case 'Finalizing': return 'bg-yellow-500';
      case 'Completed': return 'bg-green-500';
      default: return 'bg-gray-500';
    }
  };

  // Media block supporting: carousel of images, optional videos, or before/after hover
  const ProjectMedia = ({ project }: { project: Project }) => {
    const showBeforeAfter = project.beforeAfter && project.images.length >= 2;

    if (showBeforeAfter) {
      return (
        <div className="relative w-full overflow-hidden rounded-t-2xl group/media">
          <img
            src={project.images[0]}
            alt={`${project.name} before - custom jungle gym installation project progress`}
            className="w-full h-56 md:h-64 lg:h-72 object-cover transform transition-transform duration-500 will-change-transform group-hover/media:scale-[1.02]"
            loading="lazy"
          />
          <img
            src={project.images[1]}
            alt={`${project.name} after - custom jungle gym installation project progress`}
            className="absolute inset-0 w-full h-56 md:h-64 lg:h-72 object-cover opacity-0 transition-opacity duration-500 group-hover/media:opacity-100"
            loading="lazy"
          />
          <div className="absolute left-3 top-3 flex gap-2">
            <span className="px-2 py-0.5 text-xs font-semibold rounded-full bg-black/60 text-white">Before</span>
            <span className="px-2 py-0.5 text-xs font-semibold rounded-full bg-green-600 text-white opacity-0 transition-opacity duration-500 group-hover/media:opacity-100">After</span>
          </div>
        </div>
      );
    }

    return (
      <Carousel className="w-full rounded-t-2xl" opts={{ loop: true }}>
        <CarouselContent>
          {project.videos?.map((src, idx) => (
            <CarouselItem key={`video-${idx}`}>
              <video
                src={src}
                className="w-full h-56 md:h-64 lg:h-72 object-cover"
                autoPlay
                loop
                muted
                playsInline
                aria-label={`${project.name} construction video - outdoor play equipment projects`}
              />
            </CarouselItem>
          ))}
          {project.images.map((src, idx) => (
            <CarouselItem key={`img-${idx}`}>
              <img
                src={src}
                alt={`${project.name} - progress photo ${idx + 1} - playground construction Botswana`}
                className="w-full h-56 md:h-64 lg:h-72 object-cover"
                loading="lazy"
              />
            </CarouselItem>
          ))}
        </CarouselContent>
        {(project.images.length + (project.videos?.length || 0)) > 1 && <><CarouselPrevious className="left-2" /><CarouselNext className="right-2" /></>}
      </Carousel>
    );
  };

  return (
    <section id="ongoing-projects" aria-label="Ongoing custom jungle gym installation projects in Botswana" className="py-20 bg-gray-50">
      <div className="container mx-auto px-4">
        {/* SEO-friendly Title and Subtitle */}
        <div className="text-center mb-12">
          <h2 className="text-4xl font-extrabold text-gray-800 mb-4 tracking-tight">Custom Jungle Gym Installation Projects</h2>
          <p className="text-lg text-gray-600 max-w-3xl mx-auto">
            Explore our ongoing and recent playground construction in Botswana, featuring safe and durable outdoor play equipment projects for schools, resorts, and private homes.
          </p>
        </div>

        {/* Filter Buttons */}
        <div className="flex justify-center flex-wrap gap-3 mb-12">
          <Button onClick={() => setActiveTag('All')} variant={activeTag === 'All' ? 'default' : 'outline'} className="rounded-full">All Projects</Button>
          {allTags.map(tag => (
            <Button key={tag} onClick={() => setActiveTag(tag)} variant={activeTag === tag ? 'default' : 'outline'} className="rounded-full">{tag}</Button>
          ))}
        </div>

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredProjects.map((project) => (
            <Card key={project.id} className="group rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 flex flex-col border-gray-200 will-change-transform hover:-translate-y-1">
              <CardContent className="p-0">
                <ProjectMedia project={project} />
              </CardContent>
              
              <div className="p-6 flex-grow flex flex-col">
                <div className="flex-grow">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xl font-bold text-gray-900 leading-tight">{project.name}</h3>
                    <Badge className={`text-white ${getStatusColor(project.status)}`}>{project.status}</Badge>
                  </div>
                  <div className="flex items-center text-sm text-gray-500 mb-4">
                    <MapPin className="w-4 h-4 mr-2" />
                    <span>{project.location}</span>
                  </div>
                  <p className="text-gray-700 text-sm mb-4 line-clamp-3">{project.description}</p>
                  
                  {/* Progress Bar and ETA */}
                  <div className="mb-4">
                    <div className="flex justify-between items-center text-sm mb-1">
                      <span className="font-semibold text-gray-600">Progress: {project.progress}%</span>
                      <div className="flex items-center text-gray-500">
                        <Calendar className="w-4 h-4 mr-1.5" />
                        <span>ETA: {project.eta}</span>
                      </div>
                    </div>
                    <Progress value={project.progress} className="h-2" />
                  </div>
                </div>
                
                <div className="flex flex-wrap gap-2 mb-4">
                  {project.tags.map(tag => <Badge key={tag} variant="secondary">{tag}</Badge>)}
                </div>
              </div>

              <CardFooter className="p-4 bg-gray-50 rounded-b-2xl">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 w-full">
                  <Button asChild className="w-full bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 shadow-md hover:shadow-lg transition-all">
                    <Link to={`/contact?project_inquiry=${encodeURIComponent(project.name)}`} aria-label={`Book a similar project to ${project.name}`}>
                      <HardHat className="w-4 h-4 mr-2" />
                      Book a Similar Project
                    </Link>
                  </Button>
                  <Button asChild variant="outline" className="w-full border-2">
                    <a target="_blank" rel="noopener noreferrer" href={`https://wa.me/26776574262?text=${encodeURIComponent('Hi! I\'d like a similar project: ' + project.name)}`} aria-label={`WhatsApp about ${project.name}`}>
                      <MessageCircle className="w-4 h-4 mr-2" />
                      WhatsApp Us
                    </a>
                  </Button>
                </div>
              </CardFooter>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
};

export default OngoingProjects;
