import { Button } from "@/components/ui/button";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { Link } from "react-router-dom";

interface NavigationButtonsProps {
  prevLink?: string;
  prevText?: string;
  nextLink?: string;
  nextText?: string;
}

const NavigationButtons = ({ prevLink, prevText, nextLink, nextText }: NavigationButtonsProps) => {
  if (!prevLink && !nextLink) return null;
  
  return (
    <section className="py-8 bg-gradient-to-r from-jungle/5 to-playground/5">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center">
          {prevLink ? (
            <Link to={prevLink}>
              <Button 
                variant="outline" 
                className="flex items-center space-x-2 hover:bg-jungle/10 border-jungle/20"
              >
                <ChevronLeft className="h-4 w-4" />
                <span>{prevText}</span>
              </Button>
            </Link>
          ) : <div />}
          
          {nextLink ? (
            <Link to={nextLink}>
              <Button 
                variant="outline" 
                className="flex items-center space-x-2 hover:bg-playground/10 border-playground/20"
              >
                <span>{nextText}</span>
                <ChevronRight className="h-4 w-4" />
              </Button>
            </Link>
          ) : <div />}
        </div>
      </div>
    </section>
  );
};

export default NavigationButtons;