import { useState } from "react";
import { Heart, Share2, Package, Truck, Star } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";

interface Product {
  id: string;
  name: string;
  price: number;
  originalPrice?: number;
  image: string;
  category: string;
  rating?: number;
  reviews?: number;
  inStock: boolean;
  description: string;
  ageRange: string;
  features: string[];
}

interface WishlistItem {
  id: string;
  name: string;
  price: number;
  image: string;
  dateAdded: string;
}

export const useWishlist = () => {
  const { toast } = useToast();
  
  const getWishlist = (): WishlistItem[] => {
    try {
      const stored = localStorage.getItem('jungle-city-wishlist');
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  };

  const addToWishlist = (product: Product) => {
    try {
      const currentWishlist = getWishlist();
      const exists = currentWishlist.find(item => item.id === product.id);
      
      if (exists) {
        toast({
          title: "Already in Wishlist! 💝",
          description: `${product.name} is already in your wishlist.`,
        });
        return;
      }

      const wishlistItem: WishlistItem = {
        id: product.id,
        name: product.name,
        price: product.price,
        image: product.image,
        dateAdded: new Date().toISOString()
      };

      const updatedWishlist = [...currentWishlist, wishlistItem];
      localStorage.setItem('jungle-city-wishlist', JSON.stringify(updatedWishlist));
      
      toast({
        title: "Added to Wishlist! 💖",
        description: `${product.name} has been added to your wishlist.`,
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Could not add item to wishlist.",
        variant: "destructive"
      });
    }
  };

  const removeFromWishlist = (productId: string) => {
    try {
      const currentWishlist = getWishlist();
      const updatedWishlist = currentWishlist.filter(item => item.id !== productId);
      localStorage.setItem('jungle-city-wishlist', JSON.stringify(updatedWishlist));
      
      toast({
        title: "Removed from Wishlist",
        description: "Item has been removed from your wishlist.",
      });
    } catch (error) {
      toast({
        title: "Error",
        description: "Could not remove item from wishlist.",
        variant: "destructive"
      });
    }
  };

  const isInWishlist = (productId: string): boolean => {
    const wishlist = getWishlist();
    return wishlist.some(item => item.id === productId);
  };

  return {
    wishlist: getWishlist(),
    addToWishlist,
    removeFromWishlist,
    isInWishlist
  };
};

interface ProductReview {
  id: string;
  productId: string;
  customerName: string;
  rating: number;
  comment: string;
  date: string;
  verified: boolean;
}

export const useProductReviews = () => {
  const { toast } = useToast();

  const getReviews = (productId: string): ProductReview[] => {
    try {
      const stored = localStorage.getItem(`jungle-city-reviews-${productId}`);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  };

  const addReview = (productId: string, review: Omit<ProductReview, 'id' | 'productId' | 'date'>) => {
    try {
      const currentReviews = getReviews(productId);
      const newReview: ProductReview = {
        ...review,
        id: Date.now().toString(),
        productId,
        date: new Date().toISOString()
      };

      const updatedReviews = [...currentReviews, newReview];
      localStorage.setItem(`jungle-city-reviews-${productId}`, JSON.stringify(updatedReviews));
      
      toast({
        title: "Review Added! ⭐",
        description: "Thank you for your feedback!",
      });
      
      return newReview;
    } catch (error) {
      toast({
        title: "Error",
        description: "Could not add review.",
        variant: "destructive"
      });
      return null;
    }
  };

  const getAverageRating = (productId: string): { average: number; count: number } => {
    const reviews = getReviews(productId);
    if (reviews.length === 0) return { average: 0, count: 0 };
    
    const total = reviews.reduce((sum, review) => sum + review.rating, 0);
    return {
      average: Math.round((total / reviews.length) * 10) / 10,
      count: reviews.length
    };
  };

  return {
    getReviews,
    addReview,
    getAverageRating
  };
};