import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Star, MessageSquarePlus, Heart, Image as ImageIcon, Calendar, ThumbsUp, Filter, SortAsc } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { motion, AnimatePresence } from "framer-motion";

interface Testimonial {
  id: string;
  name: string;
  title?: string;
  location?: string;
  content: string;
  rating: number;
  avatar: string;
  images?: string[];
  date: string;
  likes: number;
  isLiked: boolean;
}

const STORAGE_KEY = 'jungle-city-testimonials';
const LIKES_KEY = 'jungle-city-testimonial-likes';

const Testimonials = () => {
  const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
  const [sortBy, setSortBy] = useState<'recent' | 'likes' | 'rating'>('recent');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [form, setForm] = useState({
    name: "",
    title: "",
    location: "",
    rating: 5,
    content: "",
    images: [] as string[]
  });

  const staticTestimonials: Testimonial[] = [
    {
      id: "1",
      name: "Thabo Molefe",
      title: "School Principal",
      location: "Gaborone Primary School",
      content: "Jungle City transformed our playground into a wonderful space where children love to play and learn. The quality is exceptional and the installation was professional. Our students are thrilled with the new equipment!",
      rating: 5,
      avatar: "👨‍🏫",
      date: "2024-12-15",
      likes: 24,
      isLiked: false,
      images: ["/lovable-uploads/55fbc171-993c-4b57-893f-d146532ea965.png"]
    },
    {
      id: "2",
      name: "Sarah Williams",
      title: "Parent",
      location: "Francistown",
      content: "We installed a custom jungle gym in our backyard and our kids absolutely love it! The safety features give us peace of mind while they play for hours. Best investment we've made for our family.",
      rating: 5,
      avatar: "👩‍👧‍👦",
      date: "2024-12-10",
      likes: 18,
      isLiked: false
    },
    {
      id: "3",
      name: "David Kgosana",
      title: "Parks Manager",
      location: "Maun Community Center",
      content: "The playground equipment from Jungle City has been fantastic. It's durable, safe, and the children in our community enjoy it every day. Highly recommended for any community project!",
      rating: 5,
      avatar: "👨‍💼",
      date: "2024-12-08",
      likes: 31,
      isLiked: false
    },
    {
      id: "4",
      name: "Grace Motsepe",
      title: "Daycare Owner",
      location: "Little Angels Daycare",
      content: "Professional service from start to finish. The team understood our needs and delivered a perfect playground solution for our different age groups. The children are so happy!",
      rating: 5,
      avatar: "👩‍🏫",
      date: "2024-12-05",
      likes: 15,
      isLiked: false
    },
    {
      id: "5",
      name: "Michael Johnson",
      title: "Facilities Manager",
      location: "Kasane Hotel Resort",
      content: "Our guests' children love the playground area. It's become one of our most popular family features. The equipment has held up beautifully in our climate and looks as good as new.",
      rating: 5,
      avatar: "👨‍🔧",
      date: "2024-12-01",
      likes: 27,
      isLiked: false
    },
    {
      id: "6",
      name: "Nomsa Dlamini",
      title: "Municipal Councillor",
      location: "Serowe Council",
      content: "Jungle City helped us create an inclusive playground that serves our entire community. The project was completed on time and within budget. The quality exceeds our expectations.",
      rating: 5,
      avatar: "👩‍⚖️",
      date: "2024-11-28",
      likes: 22,
      isLiked: false
    }
  ];

  useEffect(() => {
    loadTestimonials();
    loadLikes();
  }, []);

  const loadTestimonials = () => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      const userTestimonials = saved ? JSON.parse(saved) : [];
      setTestimonials([...userTestimonials, ...staticTestimonials]);
    } catch (error) {
      setTestimonials(staticTestimonials);
    }
  };

  const loadLikes = () => {
    try {
      const savedLikes = localStorage.getItem(LIKES_KEY);
      if (savedLikes) {
        const likesData = JSON.parse(savedLikes);
        setTestimonials(prev => prev.map(t => ({
          ...t,
          isLiked: likesData[t.id] || false
        })));
      }
    } catch (error) {
      // Ignore errors
    }
  };

  const saveLikes = (likesData: Record<string, boolean>) => {
    try {
      localStorage.setItem(LIKES_KEY, JSON.stringify(likesData));
    } catch (error) {
      // Ignore errors
    }
  };

  const handleLike = (testimonialId: string) => {
    const updatedTestimonials = testimonials.map(t => {
      if (t.id === testimonialId) {
        const newLikes = t.isLiked ? t.likes - 1 : t.likes + 1;
        return { ...t, likes: newLikes, isLiked: !t.isLiked };
      }
      return t;
    });
    
    setTestimonials(updatedTestimonials);
    
    // Save likes state
    const likesData: Record<string, boolean> = {};
    updatedTestimonials.forEach(t => {
      likesData[t.id] = t.isLiked;
    });
    saveLikes(likesData);
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (files) {
      const imageUrls: string[] = [];
      Array.from(files).forEach(file => {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (e.target?.result) {
            imageUrls.push(e.target.result as string);
            setForm(prev => ({ ...prev, images: [...prev.images, ...imageUrls] }));
          }
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const removeImage = (index: number) => {
    setForm(prev => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index)
    }));
  };

  const submitTestimonial = () => {
    if (!form.name.trim() || !form.content.trim()) return;

    const newTestimonial: Testimonial = {
      id: Date.now().toString(),
      name: form.name.trim(),
      title: form.title.trim() || undefined,
      location: form.location.trim() || undefined,
      content: form.content.trim(),
      rating: form.rating,
      avatar: "🧑",
      images: form.images.length > 0 ? form.images : undefined,
      date: new Date().toISOString().split('T')[0],
      likes: 0,
      isLiked: false
    };

    const updatedTestimonials = [newTestimonial, ...testimonials];
    setTestimonials(updatedTestimonials);
    
    // Save to localStorage
    const userTestimonials = updatedTestimonials.filter(t => !staticTestimonials.find(st => st.id === t.id));
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(userTestimonials));
    } catch (error) {
      // Ignore errors
    }

    // Reset form
    setForm({
      name: "",
      title: "",
      location: "",
      rating: 5,
      content: "",
      images: []
    });
    setIsDialogOpen(false);
  };

  const sortedTestimonials = [...testimonials].sort((a, b) => {
    switch (sortBy) {
      case 'recent':
        return new Date(b.date).getTime() - new Date(a.date).getTime();
      case 'likes':
        return b.likes - a.likes;
      case 'rating':
        return b.rating - a.rating;
      default:
        return 0;
    }
  });

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  return (
    <section className="py-20 bg-gradient-to-br from-background via-muted/30 to-sunshine/10">
      <div className="container mx-auto px-4">
        {/* Header */}
        <motion.div 
          className="text-center mb-16"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
        >
          <h1 className="text-4xl md:text-6xl font-bold text-jungle mb-6">
            What Our Customers Say
          </h1>
          <p className="text-xl text-muted-foreground max-w-3xl mx-auto leading-relaxed">
            Real experiences from schools, parents, and communities across Botswana. 
            Join thousands of satisfied customers who trust Jungle City for their playground needs.
          </p>
        </motion.div>

        {/* Controls */}
        <div className="flex flex-col sm:flex-row items-center justify-between mb-12 gap-4">
          {/* Sort Options */}
          <div className="flex items-center gap-3">
            <Filter className="w-5 h-5 text-muted-foreground" />
            <Select value={sortBy} onValueChange={(value: 'recent' | 'likes' | 'rating') => setSortBy(value)}>
              <SelectTrigger className="w-48">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="recent">Most Recent</SelectItem>
                <SelectItem value="likes">Most Liked</SelectItem>
                <SelectItem value="rating">Highest Rated</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Add Testimonial Button */}
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-gradient-to-r from-jungle to-playground hover:from-jungle/90 hover:to-playground/90 text-white font-semibold">
                <MessageSquarePlus className="w-4 h-4 mr-2" />
                Share Your Experience
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle className="text-2xl font-bold text-jungle">
                  Share Your Experience
                </DialogTitle>
              </DialogHeader>
              
              <div className="space-y-6">
                {/* Basic Info */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium text-foreground mb-2 block">Name *</label>
                    <Input 
                      placeholder="Your full name" 
                      value={form.name} 
                      onChange={(e) => setForm({ ...form, name: e.target.value })} 
                    />
                  </div>
                  <div>
                    <label className="text-sm font-medium text-foreground mb-2 block">Role/Title</label>
                    <Input 
                      placeholder="e.g., Parent, Teacher, Manager" 
                      value={form.title} 
                      onChange={(e) => setForm({ ...form, title: e.target.value })} 
                    />
                  </div>
                </div>

                <div>
                  <label className="text-sm font-medium text-foreground mb-2 block">Location</label>
                  <Input 
                    placeholder="e.g., Gaborone, Francistown" 
                    value={form.location} 
                    onChange={(e) => setForm({ ...form, location: e.target.value })} 
                  />
                </div>

                {/* Rating */}
                <div>
                  <label className="text-sm font-medium text-foreground mb-2 block">Rating</label>
                  <div className="flex gap-2">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button
                        key={star}
                        type="button"
                        onClick={() => setForm({ ...form, rating: star })}
                        className="text-2xl hover:scale-110 transition-transform"
                      >
                        <Star 
                          className={`w-8 h-8 ${star <= form.rating ? 'fill-sunshine text-sunshine' : 'text-muted-foreground'}`} 
                        />
                      </button>
                    ))}
                  </div>
                </div>

                {/* Comment */}
                <div>
                  <label className="text-sm font-medium text-foreground mb-2 block">Your Experience *</label>
                  <Textarea 
                    placeholder="Tell us about your experience with Jungle City..." 
                    value={form.content} 
                    onChange={(e) => setForm({ ...form, content: e.target.value })}
                    rows={4}
                    className="resize-none"
                  />
                </div>

                {/* Image Upload */}
                <div>
                  <label className="text-sm font-medium text-foreground mb-2 block">Add Photos (Optional)</label>
                  <div className="space-y-4">
                    <div className="flex items-center gap-4">
                      <label className="cursor-pointer">
                        <div className="flex items-center gap-2 px-4 py-2 border-2 border-dashed border-muted-foreground rounded-lg hover:border-jungle transition-colors">
                          <ImageIcon className="w-5 h-5" />
                          <span>Upload Images</span>
                        </div>
                        <input
                          type="file"
                          multiple
                          accept="image/*"
                          onChange={handleImageUpload}
                          className="hidden"
                        />
                      </label>
                    </div>

                    {/* Image Preview */}
                    {form.images.length > 0 && (
                      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        {form.images.map((image, index) => (
                          <div key={index} className="relative group">
                            <img 
                              src={image} 
                              alt={`Upload ${index + 1}`}
                              className="w-full h-24 object-cover rounded-lg"
                            />
                            <button
                              type="button"
                              onClick={() => removeImage(index)}
                              className="absolute top-1 right-1 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                            >
                              ×
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {/* Submit */}
                <Button 
                  onClick={submitTestimonial}
                  disabled={!form.name.trim() || !form.content.trim()}
                  className="w-full bg-gradient-to-r from-jungle to-playground hover:from-jungle/90 hover:to-playground/90 text-white font-semibold py-3"
                >
                  Submit Testimonial
                </Button>

                <p className="text-xs text-muted-foreground text-center">
                  By submitting, you agree we may display your testimonial on this site.
                </p>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        {/* Testimonials Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          <AnimatePresence>
            {sortedTestimonials.map((testimonial, index) => (
              <motion.div
                key={testimonial.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.5, delay: index * 0.1 }}
              >
                <Card className="group overflow-hidden border-2 border-border/30 hover:border-jungle/50 transition-all duration-500 hover:shadow-2xl hover:-translate-y-2 bg-gradient-to-br from-card to-card/80">
                  <CardHeader className="pb-4">
                    {/* Rating and Date */}
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-1">
                        {[...Array(testimonial.rating)].map((_, i) => (
                          <Star key={i} className="h-4 w-4 fill-sunshine text-sunshine" />
                        ))}
                      </div>
                      <div className="flex items-center gap-1 text-sm text-muted-foreground">
                        <Calendar className="w-4 h-4" />
                        {formatDate(testimonial.date)}
                      </div>
                    </div>

                    {/* Images */}
                    {testimonial.images && testimonial.images.length > 0 && (
                      <div className="mb-4">
                        <img 
                          src={testimonial.images[0]} 
                          alt="Testimonial"
                          className="w-full h-48 object-cover rounded-lg"
                        />
                      </div>
                    )}

                    {/* Content */}
                    <p className="text-muted-foreground leading-relaxed italic">
                      "{testimonial.content}"
                    </p>
                  </CardHeader>

                  <CardContent className="pt-0">
                    {/* Author Info */}
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <div className="text-2xl">
                          {testimonial.avatar}
                        </div>
                        <div>
                          <div className="font-bold text-foreground">
                            {testimonial.name}
                          </div>
                          {testimonial.title && (
                            <div className="text-sm text-jungle font-medium">
                              {testimonial.title}
                            </div>
                          )}
                          {testimonial.location && (
                            <div className="text-xs text-muted-foreground">
                              {testimonial.location}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Like Button */}
                    <div className="flex items-center justify-between pt-4 border-t border-border/30">
                      <button
                        onClick={() => handleLike(testimonial.id)}
                        className={`flex items-center gap-2 px-3 py-2 rounded-full transition-all duration-300 ${
                          testimonial.isLiked 
                            ? 'bg-red-500 text-white' 
                            : 'bg-muted/50 text-muted-foreground hover:bg-red-500 hover:text-white'
                        }`}
                      >
                        <Heart className={`w-4 h-4 ${testimonial.isLiked ? 'fill-current' : ''}`} />
                        <span className="text-sm font-medium">{testimonial.likes}</span>
                      </button>

                      {testimonial.isLiked && (
                        <Badge className="bg-green-500 text-white">
                          Liked
                        </Badge>
                      )}
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>

        {/* Trust Indicators */}
        <motion.div 
          className="mt-20 text-center"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.3 }}
        >
          <div className="bg-gradient-to-r from-jungle/10 to-playground/10 rounded-3xl p-12 border-2 border-jungle/20">
            <h3 className="text-3xl font-bold text-foreground mb-8">
              Trusted by Communities Across Botswana
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              <div className="text-center">
                <div className="text-4xl font-bold text-jungle mb-2">98%</div>
                <div className="text-muted-foreground">Client Satisfaction</div>
              </div>
              <div className="text-center">
                <div className="text-4xl font-bold text-playground mb-2">5★</div>
                <div className="text-muted-foreground">Average Rating</div>
              </div>
              <div className="text-center">
                <div className="text-4xl font-bold text-sunshine mb-2">50+</div>
                <div className="text-muted-foreground">5-Star Reviews</div>
              </div>
              <div className="text-center">
                <div className="text-4xl font-bold text-adventure mb-2">100%</div>
                <div className="text-muted-foreground">On-Time Delivery</div>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Testimonials;