const STORAGE_KEY = 'jungle-city-price-overrides';
const EDIT_MODE_KEY = 'jungle-city-edit-mode';

export type PriceOverridesMap = Record<string, number>;

function readStorage(): PriceOverridesMap {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') return parsed as PriceOverridesMap;
    return {};
  } catch {
    return {};
  }
}

function writeStorage(map: PriceOverridesMap): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(map));
  } catch {
    // ignore write errors
  }
}

export function getOverride(productId: string): number | undefined {
  const map = readStorage();
  const value = map[productId];
  return typeof value === 'number' && value > 0 ? value : undefined;
}

export function getEffectivePrice(productId: string, fallbackPrice: number): number {
  const override = getOverride(productId);
  return typeof override === 'number' ? override : fallbackPrice;
}

export function setOverride(productId: string, price: number): void {
  if (!Number.isFinite(price) || price <= 0) return;
  const map = readStorage();
  map[productId] = Math.round(price);
  writeStorage(map);
}

export function removeOverride(productId: string): void {
  const map = readStorage();
  if (productId in map) {
    delete map[productId];
    writeStorage(map);
  }
}

export function isEditingEnabled(): boolean {
  try {
    return localStorage.getItem(EDIT_MODE_KEY) === '1';
  } catch {
    return false;
  }
}

export function setEditingEnabled(value: boolean): void {
  try {
    localStorage.setItem(EDIT_MODE_KEY, value ? '1' : '0');
  } catch {
    // ignore
  }
}


