import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { MapPin, Phone, Mail, Clock, MessageCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const Contact = () => {
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    message: ""
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.message) {
      toast({
        title: "Please fill in all required fields",
        description: "Name, email, and message are required.",
        variant: "destructive"
      });
      return;
    }

    // Create WhatsApp message
    const whatsappMessage = `Hi! New contact form submission:
Name: ${formData.name}
Email: ${formData.email}
Phone: ${formData.phone || 'Not provided'}
Message: ${formData.message}`;

    window.open(`https://wa.me/26776574262?text=${encodeURIComponent(whatsappMessage)}`, "_blank");
    
    toast({
      title: "Opening WhatsApp!",
      description: "Your message will be sent via WhatsApp. We'll respond quickly!",
    });

    // Reset form
    setFormData({ name: "", email: "", phone: "", message: "" });
  };

  const handleWhatsAppClick = () => {
    toast({
      title: "Opening WhatsApp",
      description: "Chat with us instantly for quick support!",
    });
    window.open("https://wa.me/26776574262?text=Hi! I'm interested in playground equipment.", "_blank");
  };

  const handlePhoneClick = () => {
    toast({
      title: "Calling Jungle City",
      description: "Available 24/7 for emergencies!",
    });
    window.open("tel:+26771252032");
  };

  const handleEmailClick = () => {
    toast({
      title: "Opening Email",
      description: "We'll respond within 24 hours!",
    });
    window.open("mailto:info@newicecity.com");
  };


  return (
    <section id="contact" className="py-20 bg-gradient-to-br from-background via-muted/20 to-jungle/5">
      <div className="container mx-auto px-4">
        <div className="text-center mb-16">
          <h2 className="text-3xl md:text-5xl font-bold text-jungle mb-4 animate-bounce-in">
            Get In Touch
          </h2>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            Ready to create the perfect playground? Contact us via WhatsApp for instant support or use our contact form. 
            We're here to help bring your playground dreams to life!
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          {/* Contact Form */}
          <Card className="playground-card bg-gradient-to-br from-card to-card/80 border-2 border-border/30 hover:border-jungle/30 transition-all duration-300">
            <CardHeader>
              <CardTitle className="text-2xl text-foreground flex items-center">
                <MessageCircle className="mr-3 h-6 w-6 text-jungle" />
                Send WhatsApp Message
              </CardTitle>
              <p className="text-sm text-muted-foreground">
                Fill out the form below and we'll open WhatsApp with your message ready to send!
              </p>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <Input
                    type="text"
                    name="name"
                    placeholder="Your Name *"
                    value={formData.name}
                    onChange={handleInputChange}
                    className="border-2 border-border/30 focus:border-jungle transition-colors duration-300"
                    required
                  />
                </div>
                <div>
                  <Input
                    type="email"
                    name="email"
                    placeholder="Your Email *"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="border-2 border-border/30 focus:border-jungle transition-colors duration-300"
                    required
                  />
                </div>
                <div>
                  <Input
                    type="tel"
                    name="phone"
                    placeholder="Your Phone Number"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="border-2 border-border/30 focus:border-jungle transition-colors duration-300"
                  />
                </div>
                <div>
                  <Textarea
                    name="message"
                    placeholder="Tell us about your playground project *"
                    value={formData.message}
                    onChange={handleInputChange}
                    className="border-2 border-border/30 focus:border-jungle transition-colors duration-300 min-h-[120px]"
                    required
                  />
                </div>
                <Button 
                  type="submit" 
                  className="w-full bg-gradient-to-r from-jungle to-playground text-white hover:from-jungle/90 hover:to-playground/90 shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300"
                  size="lg"
                >
                  Send via WhatsApp
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Contact Information */}
          <div className="space-y-6">
            {/* WhatsApp - Primary Contact */}
            <Card 
              className="playground-card cursor-pointer bg-gradient-to-br from-jungle/10 to-jungle/5 border-2 border-jungle/30 hover:border-jungle/50 transition-all duration-300 transform hover:scale-105" 
              onClick={handleWhatsAppClick}
            >
              <CardContent className="flex items-center space-x-4 p-6">
                <div className="bg-gradient-to-br from-jungle to-jungle/80 p-4 rounded-full">
                  <MessageCircle className="h-8 w-8 text-white" />
                </div>
                <div>
                  <h3 className="font-bold text-foreground text-lg">WhatsApp Live Chat</h3>
                  <p className="text-jungle font-medium text-lg">+267 76 574 262</p>
                  <p className="text-sm text-muted-foreground">Click to chat instantly - Best way to reach us!</p>
                </div>
              </CardContent>
            </Card>

            {/* Phone */}
            <Card 
              className="playground-card cursor-pointer bg-gradient-to-br from-card to-card/80 border-2 border-border/30 hover:border-playground/40 transition-all duration-300 transform hover:scale-105" 
              onClick={handlePhoneClick}
            >
              <CardContent className="flex items-center space-x-4 p-6">
                <div className="bg-gradient-to-br from-playground to-playground/80 p-3 rounded-full">
                  <Phone className="h-6 w-6 text-white" />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">Phone</h3>
                  <p className="text-playground font-medium">+267 71 252 032</p>
                  <p className="text-sm text-muted-foreground">Available 24/7 for emergencies</p>
                </div>
              </CardContent>
            </Card>

            {/* Email */}
            <Card 
              className="playground-card cursor-pointer bg-gradient-to-br from-card to-card/80 border-2 border-border/30 hover:border-adventure/40 transition-all duration-300 transform hover:scale-105" 
              onClick={handleEmailClick}
            >
              <CardContent className="flex items-center space-x-4 p-6">
                <div className="bg-gradient-to-br from-adventure to-adventure/80 p-3 rounded-full">
                  <Mail className="h-6 w-6 text-white" />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">Email</h3>
                  <p className="text-adventure font-medium">info@newicecity.com</p>
                  <p className="text-sm text-muted-foreground">We'll respond within 24 hours</p>
                </div>
              </CardContent>
            </Card>


            {/* Address */}
            <Card className="playground-card bg-gradient-to-br from-card to-card/80 border-2 border-border/30">
              <CardContent className="flex items-center space-x-4 p-6">
                <div className="bg-gradient-to-br from-sunshine to-sunshine/80 p-3 rounded-full">
                  <MapPin className="h-6 w-6 text-foreground" />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">Address</h3>
                  <p className="text-sunshine font-medium"> Block 3</p>
                  <p className="text-sunshine font-medium">Gaborone, Botswana</p>
                </div>
              </CardContent>
            </Card>

            {/* Business Hours */}
            <Card className="playground-card bg-gradient-to-br from-card to-card/80 border-2 border-border/30">
              <CardContent className="flex items-center space-x-4 p-6">
                <div className="bg-gradient-to-br from-muted to-muted/80 p-3 rounded-full">
                  <Clock className="h-6 w-6 text-foreground" />
                </div>
                <div>
                  <h3 className="font-bold text-foreground">Business Hours</h3>
                  <p className="text-sm text-muted-foreground">Mon - Fri: 8:00 AM - 5:00 PM</p>
                  <p className="text-sm text-muted-foreground">Sat: 8:00 AM - 2:00 PM</p>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Contact;
