import { useEffect, useMemo, useState } from "react";
import Navigation from "@/components/Navigation";
import Footer from "@/components/Footer";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Helmet } from "react-helmet-async";
import { formatCurrency } from "@/utils/currency";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { isEditingEnabled } from "@/utils/priceOverrides";
import { handleImageError } from "@/utils/image-utils";
import { ImportedProduct } from "@/types/product";
import { useToast } from "@/hooks/use-toast";
import { useNavigate, Link } from "react-router-dom";

const RecycledPlasticWoodJungleGyms = () => {
  const [items, setItems] = useState<ImportedProduct[]>([]);
  const [editedMainImage, setEditedMainImage] = useState<Record<string, string>>({});
  const [editedGallery, setEditedGallery] = useState<Record<string, string>>({});
  const { toast } = useToast();
  const navigate = useNavigate();

  const handleExploreProducts = () => {
    try {
      console.log('Navigating to products page...');
      toast({
        title: "Exploring Products! 🛍️",
        description: "Taking you to our complete product catalog...",
      });
      navigate('/products');
    } catch (error) {
      console.error('Navigation error:', error);
      toast({
        title: "Navigation Error",
        description: "Redirecting to products page...",
        variant: "destructive"
      });
      // Fallback to window.location if navigate fails
      window.location.href = '/products';
    }
  };

  const handleGetQuote = () => {
    toast({
      title: "Get Your Free Quote!",
      description: "We'll contact you within 24 hours via WhatsApp or phone.",
    });
    window.open("https://wa.me/26776574262?text=Hi! I'd like to get a free quote for recycled plastic wood jungle gyms.", "_blank");
  };

  // Fallback seed products for this category (auto-added if none are present)
  const seedEcoProducts: ImportedProduct[] = [
    {
      id: "eco-polywood-bridge-towers",
      name: "Polywood Bridge & Towers Jungle Gym",
      description:
        "Durable recycled plastic wood playset with dual towers joined by a rope bridge. No rot, no repainting — perfect for Botswana heat and rain.",
      image: "/images/eco/IMG-20151130-WA0008.png",
      images: [
        "/images/eco/IMG-20151130-WA0008.png",
        "/images/eco/IMG-20151130-WA0009.png"
      ],
      fullDescription:
        "Built from UV-stable recycled plastic (polywood) that never needs varnish. Includes two lookout decks, a safe rope bridge, access ladder and swing beam.",
      productInfo: [
        "Recycled plastic lumber — splinter free",
        "UV and weather resistant • Low maintenance",
        "Includes rope bridge and double tower decks",
        "Optional swing seats and slide add-ons"
      ],
      category: "Recycled Plastic Wood Jungle Gyms",
      price: 36500,
      originalZARPrice: 24000,
      inStock: true,
      availabilityText: "Made to order",
      link: "/contact",
      shippingNotes: "Manufactured to spec • Botswana delivery available",
      shippingTag: "Custom"
    },
    {
      id: "eco-polywood-coastal-set",
      name: "Coastal Polywood Adventure Set",
      description:
        "Triple-tower configuration with tunnel, slide and swings. Polywood structure resists moisture and termites.",
      image: "/images/eco/IMG-20151130-WA0009.png",
      images: [
        "/images/eco/IMG-20151130-WA0009.png",
        "/images/eco/IMG-20151130-WA0008.png"
      ],
      fullDescription:
        "Ideal for schools and lodges near the Okavango or Chobe where humidity and sun exposure are high. Tunnel section in HDPE with safe edges.",
      productInfo: [
        "3 towers with connector tunnel",
        "Slide and 2-seat swing beam",
        "Galvanized hardware • Zero painting",
        "Footings cast in concrete for stability"
      ],
      category: "Recycled Plastic Wood Jungle Gyms",
      price: 48500,
      originalZARPrice: 32000,
      inStock: true,
      availabilityText: "In stock",
      link: "/contact",
      shippingNotes: "Professional installation across Botswana",
      shippingTag: "Installation"
    },
    {
      id: "eco-polywood-starter",
      name: "Polywood Starter Fort with Slide",
      description:
        "Compact single-tower set with ladder climb and 3m slide. Perfect entry model for homes and daycares.",
      image: "/images/eco/IMG-20151130-WA0008.png",
      images: [
        "/images/eco/IMG-20151130-WA0008.png",
        "/images/eco/IMG-20151130-WA0009.png"
      ],
      fullDescription:
        "All the benefits of recycled plastic wood in a compact footprint. No splinters, no rot, easy to wash down.",
      productInfo: [
        "Single tower with safety rails",
        "3m fiberglass slide option",
        "Anti-slip ladder rungs",
        "Ages 3–10 • 2-year warranty"
      ],
      category: "Recycled Plastic Wood Jungle Gyms",
      price: 32500,
      originalZARPrice: 15000,
      inStock: true,
      availabilityText: "Made to order",
      link: "/contact",
      shippingNotes: "Delivered and installed on request",
      shippingTag: "Custom"
    },
    {
      id: "eco-polywood-swing-beam",
      name: "Polywood Swing Beam (2 Seat)",
      description:
        "Low-maintenance recycled plastic swing beam with two heavy-duty seats and stainless chains.",
      image: "/images/eco/IMG-20151130-WA0009.png",
      images: [
        "/images/eco/IMG-20151130-WA0009.png",
        "/images/eco/IMG-20151130-WA0008.png"
      ],
      fullDescription:
        "Engineered for harsh sun with UV-stable pigments. Polywood members won’t warp or split.",
      productInfo: [
        "Stainless steel chains and fixings",
        "Seat options: flat, toddler, inclusive",
        "Termite and rot proof",
        "Fast installation"
      ],
      category: "Recycled Plastic Wood Jungle Gyms",
      price: 14500,
      originalZARPrice: 9500,
      inStock: true,
      availabilityText: "In stock",
      link: "/contact",
      shippingNotes: "Ships countrywide • Install available",
      shippingTag: "Local Delivery"
    }
  ];

  useEffect(() => {
    try {
      const raw = localStorage.getItem("jungle-city-imported-products");
      if (raw) {
        const parsed = JSON.parse(raw) as ImportedProduct[];
        const filtered = parsed.filter((p) =>
          p.category === "Recycled Plastic Wood Jungle Gyms" ||
          /recycled|polywood|composite|hdpe|plastic\s*wood/i.test(p.name)
        );
        if (filtered.length > 0) {
          setItems(filtered);
        } else {
          // Seed defaults and persist alongside existing data
          const merged = [...parsed, ...seedEcoProducts];
          localStorage.setItem("jungle-city-imported-products", JSON.stringify(merged));
          setItems(seedEcoProducts);
        }
      } else {
        // No storage yet — initialize with seed data
        localStorage.setItem("jungle-city-imported-products", JSON.stringify(seedEcoProducts));
        setItems(seedEcoProducts);
      }
    } catch {}
  }, []);

  useEffect(() => {
    const nextMain: Record<string, string> = {};
    const nextGallery: Record<string, string> = {};
    items.forEach((p) => {
      nextMain[p.id] = p.image || '';
      const gallery = Array.isArray(p.images) ? p.images.join(', ') : '';
      nextGallery[p.id] = gallery;
    });
    setEditedMainImage(nextMain);
    setEditedGallery(nextGallery);
  }, [items]);

  return (
    <>
      <Helmet>
        <title>Recycled Plastic Wood Jungle Gyms • Jungle City</title>
        <meta name="description" content="Durable, eco-friendly recycled plastic wood jungle gyms for Botswana. Explore images, specs, prices and availability." />
        <link rel="canonical" href="https://i.postimg.cc/CxW0VVLX/IMG-20150721-WA0008.png" />
      </Helmet>
      <Navigation />
      <main className="min-h-screen bg-background pt-24 pb-12">
        <section className="container mx-auto px-4">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-foreground">Recycled Plastic Wood Jungle Gyms</h1>
            <p className="text-muted-foreground">Eco-friendly, weather-resistant playground structures ideal for Botswana conditions.</p>
            
            <div className="flex flex-col sm:flex-row gap-4 mt-6">
              <Link 
                to="/products"
                className="inline-flex items-center justify-center bg-jungle hover:bg-jungle/90 text-white px-8 py-3 text-lg font-semibold shadow-lg hover:shadow-xl transition-all duration-300 cursor-pointer rounded-md"
              >
                🛍️ Explore Our Products
              </Link>
              <Button 
                onClick={handleGetQuote}
                variant="outline"
                className="border-2 border-jungle text-jungle hover:bg-jungle hover:text-white px-8 py-3 text-lg font-semibold shadow-lg hover:shadow-xl transition-all duration-300 cursor-pointer"
                type="button"
              >
                💬 Get Free Quote Today
              </Button>
            </div>
          </div>

          {items.length === 0 ? (
            <div className="text-center py-20">
              <h2 className="text-xl font-semibold mb-2">No items yet</h2>
              <p className="text-muted-foreground">Import products via the admin importer to populate this category.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {items.map((p) => (
                <Card key={p.id} className="overflow-hidden border-2 border-border/50">
                  <div className="relative">
                    <img 
                      src={p.image} 
                      alt={p.name} 
                      className="w-full h-56 object-cover" 
                      loading="lazy"
                      onError={handleImageError}
                    />
                    <Badge className="absolute top-2 left-2 bg-jungle">Eco</Badge>
                  </div>
                  <CardContent className="p-4">
                    <h3 className="font-semibold line-clamp-2 mb-1">
                      <a href={p.link} target="_blank" rel="noopener noreferrer" className="underline text-jungle hover:text-jungle/80">
                        {p.name}
                      </a>
                    </h3>
                    <p className="text-sm text-muted-foreground line-clamp-3">{p.description}</p>
                    {p.productInfo && p.productInfo.length > 0 && (
                      <ul className="mt-2 text-sm list-disc list-inside space-y-1">
                        {p.productInfo.slice(0, 4).map((line, i) => (
                          <li key={i}>{line}</li>
                        ))}
                      </ul>
                    )}
                    <div className="flex items-center justify-between mt-3">
                      <div className="text-sm">
                        <div className="font-semibold text-jungle">{formatCurrency(p.price, 'BWP')}</div>
                        <div className="text-xs text-muted-foreground">{formatCurrency(p.originalZARPrice, 'ZAR')}</div>
                      </div>
                      <div className="text-xs">
                        <Badge variant="outline">{p.availabilityText || (p.inStock ? 'In stock' : 'Out of stock')}</Badge>
                      </div>
                    </div>
                    
                    <div className="mt-4">
                      <Button 
                        onClick={() => {
                          toast({
                            title: "Quote Request Sent! 📋",
                            description: `We'll contact you soon about ${p.name}.`,
                          });
                          window.open(`https://wa.me/26776574262?text=Hi! I'd like a quote for ${p.name} with professional installation.`, "_blank");
                        }}
                        className="w-full bg-jungle hover:bg-jungle/90 text-white"
                        size="sm"
                      >
                        Get Quote for This Item
                      </Button>
                    </div>

                    {isEditingEnabled() && (
                      <div className="mt-4 space-y-2 border-t pt-3">
                        <div className="text-xs font-semibold text-foreground/80">Edit Images (saved to browser)</div>
                        <div className="grid grid-cols-1 gap-2">
                          <Input
                            placeholder="Main image URL"
                            value={editedMainImage[p.id] ?? ''}
                            onChange={(e) => setEditedMainImage((prev) => ({ ...prev, [p.id]: e.target.value }))}
                          />
                          <Input
                            placeholder="Gallery URLs (comma-separated)"
                            value={editedGallery[p.id] ?? ''}
                            onChange={(e) => setEditedGallery((prev) => ({ ...prev, [p.id]: e.target.value }))}
                          />
                          <div className="flex gap-2">
                            <Button
                              className="bg-jungle hover:bg-jungle/90"
                              size="sm"
                              onClick={() => {
                                const main = (editedMainImage[p.id] || '').trim();
                                const galleryCsv = editedGallery[p.id] || '';
                                const gallery = galleryCsv
                                  .split(',')
                                  .map((s) => s.trim())
                                  .filter((s) => s.length > 0);

                                setItems((prev) => prev.map((it) => it.id === p.id ? {
                                  ...it,
                                  image: main || it.image,
                                  images: gallery.length ? gallery : it.images,
                                } : it));

                                try {
                                  const raw = localStorage.getItem('jungle-city-imported-products');
                                  if (raw) {
                                    const arr = JSON.parse(raw) as ImportedProduct[];
                                    const updated = arr.map((it) => it.id === p.id ? {
                                      ...it,
                                      image: main || it.image,
                                      images: gallery.length ? gallery : it.images,
                                    } : it);
                                    localStorage.setItem('jungle-city-imported-products', JSON.stringify(updated));
                                  }
                                } catch {}
                              }}
                            >
                              Save Images
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                setEditedMainImage((prev) => ({ ...prev, [p.id]: p.image || '' }));
                                setEditedGallery((prev) => ({ ...prev, [p.id]: Array.isArray(p.images) ? p.images.join(', ') : '' }));
                              }}
                            >
                              Reset
                            </Button>
                          </div>
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </section>
      </main>
      <Footer />
    </>
  );
};

export default RecycledPlasticWoodJungleGyms;

