import { useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import GalleryCard from "./GalleryCard";
import type { GalleryItem } from "@/data/gallery";

type Props = {
  items: GalleryItem[];
  onOpen: (index: number) => void;
};

export default function GalleryGrid({ items, onOpen }: Props) {
  const variants = useMemo(() => ({
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 120, damping: 16 } },
  }), []);

  return (
    <motion.div initial="hidden" animate="show" className="columns-1 sm:columns-2 lg:columns-3 xl:columns-4 gap-4 [column-fill:_balance]"><AnimatePresence>
      {items.map((it, idx) => (
        <motion.div key={it.id} variants={variants} className="mb-4 break-inside-avoid">
          <GalleryCard title={it.title} category={it.category} location={it.location} src={it.src} onClick={() => onOpen(idx)} />
        </motion.div>
      ))}
    </AnimatePresence></motion.div>
  );
}


