import { useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";

type Props = {
  category: string;
  setCategory: (v: string) => void;
  q: string;
  setQ: (v: string) => void;
  sort: string;
  setSort: (v: string) => void;
  tags: string[];
  toggleTag: (t: string) => void;
  clearAll: () => void;
  availableTags: string[];
};

const CATEGORIES = ["All", "Jungle Gyms", "Playgrounds", "Pool Areas", "Repairs", "Before/After"];
const SORTS = [
  { key: "new", label: "Newest" },
  { key: "old", label: "Oldest" },
  { key: "liked", label: "Most Liked" },
];

export default function GalleryFilters({ category, setCategory, q, setQ, sort, setSort, tags, toggleTag, clearAll, availableTags }: Props) {
  const uniqueTags = useMemo(() => Array.from(new Set(availableTags)).slice(0, 20), [availableTags]);

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
        <div>
          <h2 className="text-3xl md:text-4xl font-bold tracking-tight">Project Gallery</h2>
          <p className="text-muted-foreground">Explore our work across Botswana</p>
        </div>
        <div className="flex gap-2 items-center">
          {SORTS.map((s) => (
            <Button key={s.key} variant={sort === s.key ? "default" : "outline"} onClick={() => setSort(s.key)}>{s.label}</Button>
          ))}
          <div className="relative">
            <Input placeholder="Search title, tags, location" value={q} onChange={(e) => setQ(e.target.value)} className="w-64" />
          </div>
        </div>
      </div>

      <div className="flex flex-wrap gap-2">
        {CATEGORIES.map((c) => (
          <Button key={c} variant={category === c ? "default" : "outline"} className="rounded-full" onClick={() => setCategory(c)}>
            {c}
          </Button>
        ))}
      </div>

      <div className="flex flex-wrap gap-2">
        {uniqueTags.map((t) => (
          <Badge key={t} onClick={() => toggleTag(t)} className={`cursor-pointer ${tags.includes(t) ? "bg-jungle text-white" : ""}`}>{t}</Badge>
        ))}
        {(q || tags.length > 0 || category !== "All") && (
          <Button variant="ghost" onClick={clearAll}>Clear All</Button>
        )}
      </div>
    </div>
  );
}


