"use client";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { SafeImage } from "@/components/ui/safe-image";
import { ChevronLeft, ChevronRight, Share2, Heart } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { useState } from "react";

type Props = {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  src: string;
  title: string;
  caption?: string;
  onPrev?: () => void;
  onNext?: () => void;
  likeCount?: number;
  isLiked?: boolean;
  onLike?: () => void;
  share?: () => void;
  comments?: { id: string; text: string; date: string }[];
  onAddComment?: (text: string) => void;
};

export default function GalleryLightbox({ open, onOpenChange, src, title, caption, onPrev, onNext, likeCount, isLiked, onLike, share, comments = [], onAddComment }: Props) {
  const [draft, setDraft] = useState("");
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-5xl p-2 sm:p-4">
        <AnimatePresence mode="wait">
          {open && (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
              <div className="relative">
                <div className="rounded-md bg-black">
                  <div className="aspect-[16/9]">
                    <div onContextMenu={(e) => e.preventDefault()} className="h-full w-full select-none">
                      <SafeImage src={src} alt={title} className="h-full w-full object-contain pointer-events-none" draggable={false} />
                    </div>
                  </div>
                </div>
                <div className="mt-3 flex items-center justify-between px-1">
                  <div className="text-sm text-muted-foreground">
                    <span className="font-medium text-foreground">{title}</span>
                    {caption ? <span className="ml-2">{caption}</span> : null}
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={onLike} className={`inline-flex items-center gap-1 rounded-full border px-3 py-1 text-sm ${isLiked ? 'bg-red-50 border-red-200 text-red-600' : ''}`}>
                      <Heart className={`h-4 w-4 ${isLiked ? 'fill-red-500 text-red-500' : ''}`} /> {likeCount ?? 0}
                    </button>
                    <button onClick={share} className="inline-flex items-center gap-1 rounded-full border px-3 py-1 text-sm">
                      <Share2 className="h-4 w-4" /> Share
                    </button>
                  </div>
                </div>
                {onPrev && (
                  <button aria-label="Previous" className="absolute left-2 top-1/2 -translate-y-1/2 rounded-full bg-background/80 p-2 shadow ring-1 ring-border" onClick={onPrev}>
                    <ChevronLeft className="h-5 w-5" />
                  </button>
                )}
                {onNext && (
                  <button aria-label="Next" className="absolute right-2 top-1/2 -translate-y-1/2 rounded-full bg-background/80 p-2 shadow ring-1 ring-border" onClick={onNext}>
                    <ChevronRight className="h-5 w-5" />
                  </button>
                )}
                {/* Comments */}
                <div className="mt-4 border-t pt-3">
                  <p className="text-sm font-medium mb-2">Comments</p>
                  <div className="space-y-2 max-h-40 overflow-auto pr-1">
                    {comments.length === 0 ? (
                      <p className="text-xs text-muted-foreground">No comments yet.</p>
                    ) : (
                      comments.map((c) => (
                        <div key={c.id} className="text-sm"><span className="text-foreground">{c.text}</span><span className="ml-2 text-xs text-muted-foreground">{new Date(c.date).toLocaleDateString()}</span></div>
                      ))
                    )}
                  </div>
                  <div className="mt-3 flex gap-2">
                    <input value={draft} onChange={(e) => setDraft(e.target.value)} placeholder="Write a comment" className="flex-1 rounded-md border px-3 py-2 text-sm" />
                    <button
                      className="rounded-md border px-3 py-2 text-sm"
                      onClick={() => { if (draft.trim() && onAddComment) { onAddComment(draft.trim()); setDraft(""); } }}
                    >
                      Post
                    </button>
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </DialogContent>
    </Dialog>
  );
}


