import { useState } from "react";
import Navigation from "@/components/Navigation";
import Footer from "@/components/Footer";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { useCart } from "@/contexts/CartContext";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, CreditCard, Smartphone, Building, MessageCircle } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { Helmet } from "react-helmet-async";

const Checkout = () => {
  const { state, clearCart } = useCart();
  const { toast } = useToast();
  const navigate = useNavigate();
  
  const [formData, setFormData] = useState({
    email: "",
    firstName: "",
    lastName: "",
    phone: "",
    address: "",
    city: "",
    postalCode: "",
    paymentMethod: "whatsapp",
    installationNeeded: false,
    agreeToTerms: false
  });

  const [isProcessing, setIsProcessing] = useState(false);

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-BW', {
      style: 'currency',
      currency: 'BWP',
      minimumFractionDigits: 0
    }).format(price);
  };

  const deliveryFee = state.total >= 5000 ? 0 : 500;
  const installationFee = formData.installationNeeded ? 1500 : 0;
  const totalAmount = state.total + deliveryFee + installationFee;

  const handleInputChange = (field: string, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleWhatsAppOrder = () => {
    if (!formData.agreeToTerms) {
      toast({
        title: "Terms Required",
        description: "Please agree to the terms and conditions to continue.",
        variant: "destructive"
      });
      return;
    }

    if (!formData.firstName || !formData.phone || !formData.address) {
      toast({
        title: "Missing Information",
        description: "Please fill in all required fields.",
        variant: "destructive"
      });
      return;
    }

    const orderDetails = `
🛒 *JUNGLE CITY ORDER*

👤 *Customer Details:*
Name: ${formData.firstName} ${formData.lastName}
Phone: ${formData.phone}
Email: ${formData.email}
Address: ${formData.address}, ${formData.city} ${formData.postalCode}

📦 *Order Items:*
${state.items.map(item => `• ${item.name} x ${item.quantity} - ${formatPrice(item.price * item.quantity)}`).join('\n')}

💰 *Order Summary:*
Subtotal: ${formatPrice(state.total)}
Delivery: ${formatPrice(deliveryFee)} ${deliveryFee === 0 ? '(FREE)' : ''}
${formData.installationNeeded ? `Installation: ${formatPrice(installationFee)}` : ''}
*TOTAL: ${formatPrice(totalAmount)}*

🔧 Installation Needed: ${formData.installationNeeded ? 'Yes' : 'No'}
💳 Payment Method: ${formData.paymentMethod === 'whatsapp' ? 'WhatsApp Coordination' : formData.paymentMethod}

Please confirm this order and provide payment instructions. Thank you! 🙏`;

    const encodedMessage = encodeURIComponent(orderDetails);
    window.open(`https://wa.me/26776574262?text=${encodedMessage}`, "_blank");
    
    toast({
      title: "Order Sent!",
      description: "Your order has been sent via WhatsApp. We'll contact you shortly!",
    });
    
    // Clear cart after successful order
    setTimeout(() => {
      clearCart();
      navigate('/');
    }, 2000);
  };

  const handlePaymentSubmit = async () => {
    setIsProcessing(true);
    
    if (formData.paymentMethod === 'whatsapp') {
      handleWhatsAppOrder();
    } else {
      // Future implementation for other payment methods
      toast({
        title: "Payment Method Coming Soon",
        description: "This payment method will be available soon. Please use WhatsApp for now.",
      });
    }
    
    setIsProcessing(false);
  };

  if (state.items.length === 0) {
    return (
      <>
        <Navigation />
        <div className="min-h-screen bg-background pt-24 flex items-center justify-center">
          <div className="text-center">
            <h1 className="text-2xl font-bold text-foreground mb-4">Your cart is empty</h1>
            <p className="text-muted-foreground mb-6">Add some products to your cart before checkout.</p>
            <Button onClick={() => navigate('/store')} className="bg-jungle hover:bg-jungle/90">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Store
            </Button>
          </div>
        </div>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Helmet>
        <title>Checkout - Jungle City Botswana</title>
        <meta name="description" content="Secure checkout for your playground equipment order in Botswana." />
      </Helmet>
      
      <div className="min-h-screen bg-background">
        <Navigation />
        
        <div className="pt-24 pb-12">
          <div className="container mx-auto px-4">
            <div className="mb-8">
              <Button variant="outline" onClick={() => navigate('/store')} className="mb-4">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Store
              </Button>
              <h1 className="text-3xl font-bold text-foreground">Checkout</h1>
              <p className="text-muted-foreground">Complete your order details below</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Order Form */}
              <div className="lg:col-span-2 space-y-6">
                {/* Customer Information */}
                <Card>
                  <CardHeader>
                    <CardTitle>Customer Information</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <Label htmlFor="firstName">First Name *</Label>
                        <Input
                          id="firstName"
                          value={formData.firstName}
                          onChange={(e) => handleInputChange('firstName', e.target.value)}
                          placeholder="Enter your first name"
                          required
                        />
                      </div>
                      <div>
                        <Label htmlFor="lastName">Last Name</Label>
                        <Input
                          id="lastName"
                          value={formData.lastName}
                          onChange={(e) => handleInputChange('lastName', e.target.value)}
                          placeholder="Enter your last name"
                        />
                      </div>
                    </div>
                    <div>
                      <Label htmlFor="email">Email</Label>
                      <Input
                        id="email"
                        type="email"
                        value={formData.email}
                        onChange={(e) => handleInputChange('email', e.target.value)}
                        placeholder="your.email@example.com"
                      />
                    </div>
                    <div>
                      <Label htmlFor="phone">Phone Number *</Label>
                      <Input
                        id="phone"
                        value={formData.phone}
                        onChange={(e) => handleInputChange('phone', e.target.value)}
                        placeholder="+267 71252032"
                        required
                      />
                    </div>
                  </CardContent>
                </Card>

                {/* Delivery Address */}
                <Card>
                  <CardHeader>
                    <CardTitle>Delivery Address</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div>
                      <Label htmlFor="address">Street Address *</Label>
                      <Input
                        id="address"
                        value={formData.address}
                        onChange={(e) => handleInputChange('address', e.target.value)}
                        placeholder="Enter your full address"
                        required
                      />
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <Label htmlFor="city">City</Label>
                        <Input
                          id="city"
                          value={formData.city}
                          onChange={(e) => handleInputChange('city', e.target.value)}
                          placeholder="e.g., Gaborone, Francistown"
                        />
                      </div>
                      <div>
                        <Label htmlFor="postalCode">Postal Code</Label>
                        <Input
                          id="postalCode"
                          value={formData.postalCode}
                          onChange={(e) => handleInputChange('postalCode', e.target.value)}
                          placeholder="Optional"
                        />
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* Additional Services */}
                <Card>
                  <CardHeader>
                    <CardTitle>Additional Services</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex items-center space-x-2">
                      <Checkbox
                        id="installation"
                        checked={formData.installationNeeded}
                        onCheckedChange={(checked) => handleInputChange('installationNeeded', checked)}
                      />
                      <Label htmlFor="installation" className="text-sm">
                        Professional Installation Service (+{formatPrice(1500)})
                      </Label>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      Our certified technicians will install your playground equipment safely and securely.
                    </p>
                  </CardContent>
                </Card>

                {/* Payment Method */}
                <Card>
                  <CardHeader>
                    <CardTitle>Payment Method</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <RadioGroup
                      value={formData.paymentMethod}
                      onValueChange={(value) => handleInputChange('paymentMethod', value)}
                    >
                      <div className="flex items-center space-x-2 p-4 border rounded-lg">
                        <RadioGroupItem value="whatsapp" id="whatsapp" />
                        <Label htmlFor="whatsapp" className="flex items-center gap-2 cursor-pointer">
                          <MessageCircle className="w-4 h-4 text-playground" />
                          WhatsApp Coordination (Recommended)
                        </Label>
                      </div>
                      <div className="flex items-center space-x-2 p-4 border rounded-lg opacity-50">
                        <RadioGroupItem value="card" id="card" disabled />
                        <Label htmlFor="card" className="flex items-center gap-2">
                          <CreditCard className="w-4 h-4" />
                          Credit/Debit Card (Coming Soon)
                        </Label>
                      </div>
                      <div className="flex items-center space-x-2 p-4 border rounded-lg opacity-50">
                        <RadioGroupItem value="mobile" id="mobile" disabled />
                        <Label htmlFor="mobile" className="flex items-center gap-2">
                          <Smartphone className="w-4 h-4" />
                          Mobile Money (Coming Soon)
                        </Label>
                      </div>
                      <div className="flex items-center space-x-2 p-4 border rounded-lg opacity-50">
                        <RadioGroupItem value="bank" id="bank" disabled />
                        <Label htmlFor="bank" className="flex items-center gap-2">
                          <Building className="w-4 h-4" />
                          Bank Transfer (Coming Soon)
                        </Label>
                      </div>
                    </RadioGroup>
                    
                    {formData.paymentMethod === 'whatsapp' && (
                      <div className="mt-4 p-4 bg-playground/10 rounded-lg border border-playground/20">
                        <p className="text-sm text-foreground">
                          <strong>WhatsApp Coordination:</strong> Your order details will be sent via WhatsApp. 
                          Our team will coordinate payment options including Orange Money, MyZaka, bank transfer, or cash on delivery.
                        </p>
                      </div>
                    )}
                  </CardContent>
                </Card>

                {/* Terms and Conditions */}
                <Card>
                  <CardContent className="pt-6">
                    <div className="flex items-start space-x-2">
                      <Checkbox
                        id="terms"
                        checked={formData.agreeToTerms}
                        onCheckedChange={(checked) => handleInputChange('agreeToTerms', checked)}
                      />
                      <Label htmlFor="terms" className="text-sm leading-relaxed">
                        I agree to the terms and conditions, including delivery terms and return policy. 
                        I understand that custom playground equipment may have longer delivery times.
                      </Label>
                    </div>
                  </CardContent>
                </Card>
              </div>

              {/* Order Summary */}
              <div className="lg:col-span-1">
                <Card className="sticky top-24">
                  <CardHeader>
                    <CardTitle>Order Summary</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {/* Order Items */}
                    <div className="space-y-3">
                      {state.items.map((item) => (
                        <div key={item.id} className="flex items-center space-x-3">
                          <img 
                            src={item.image} 
                            alt={item.name}
                            className="w-12 h-12 object-cover rounded-md"
                          />
                          <div className="flex-1">
                            <h4 className="font-medium text-sm">{item.name}</h4>
                            <p className="text-xs text-muted-foreground">Qty: {item.quantity}</p>
                          </div>
                          <span className="font-semibold text-sm">
                            {formatPrice(item.price * item.quantity)}
                          </span>
                        </div>
                      ))}
                    </div>

                    <Separator />

                    {/* Price Breakdown */}
                    <div className="space-y-2">
                      <div className="flex justify-between text-sm">
                        <span>Subtotal:</span>
                        <span>{formatPrice(state.total)}</span>
                      </div>
                      <div className="flex justify-between text-sm">
                        <span>Delivery:</span>
                        <span>
                          {deliveryFee === 0 ? (
                            <Badge variant="secondary" className="text-xs">FREE</Badge>
                          ) : (
                            formatPrice(deliveryFee)
                          )}
                        </span>
                      </div>
                      {formData.installationNeeded && (
                        <div className="flex justify-between text-sm">
                          <span>Installation:</span>
                          <span>{formatPrice(installationFee)}</span>
                        </div>
                      )}
                      <Separator />
                      <div className="flex justify-between font-bold text-lg">
                        <span>Total:</span>
                        <span className="text-jungle">{formatPrice(totalAmount)}</span>
                      </div>
                    </div>

                    {state.total >= 5000 && (
                      <div className="p-3 bg-jungle/10 rounded-lg border border-jungle/20">
                        <p className="text-sm text-jungle font-medium">
                          🎉 You qualify for FREE delivery!
                        </p>
                      </div>
                    )}

                    <Button
                      onClick={handlePaymentSubmit}
                      disabled={isProcessing || !formData.agreeToTerms}
                      className="w-full bg-jungle hover:bg-jungle/90 text-white"
                      size="lg"
                    >
                      {isProcessing ? "Processing..." : "Complete Order"}
                    </Button>

                    <p className="text-xs text-muted-foreground text-center">
                      Secure checkout powered by Jungle City. 
                      Your information is protected and encrypted.
                    </p>
                  </CardContent>
                </Card>
              </div>
            </div>
          </div>
        </div>

        <Footer />
      </div>
    </>
  );
};

export default Checkout;