import Navigation from "@/components/Navigation";
import Footer from "@/components/Footer";
import NavigationButtons from "@/components/NavigationButtons";
import { Helmet } from "react-helmet-async";
import CompletedProjects from "@/components/CompletedProjects";
import ErrorBoundary from "@/components/ErrorBoundary";

const Projects = () => {
  return (
    <>
      <Helmet>
        <title>Our Projects Portfolio | Jungle City Botswana</title>
        <meta
          name="description"
          content="View our completed playground installations across Botswana. From residential jungle gyms to commercial playground equipment for schools and resorts."
        />
        <link rel="canonical" href="https://junglecity.newicecity.com/projects" />
      </Helmet>

      <div className="min-h-screen">
        <Navigation />
        <main className="pt-16">
          <section className="py-20 bg-gradient-to-br from-jungle/5 to-playground/5">
            <div className="container mx-auto px-4">
              <div className="text-center mb-12">
                <h1 className="text-4xl md:text-5xl font-bold mb-6 bg-gradient-to-r from-jungle to-playground bg-clip-text text-transparent">
                  Our Projects Portfolio
                </h1>
                <p className="text-xl text-muted-foreground max-w-3xl mx-auto leading-relaxed">
                  Explore our completed playground installations across Botswana. From residential backyard setups to commercial play areas.
                </p>
              </div>
              <ErrorBoundary>
                <CompletedProjects />
              </ErrorBoundary>
            </div>
          </section>

          <NavigationButtons
            prevLink="/gallery"
            prevText="Gallery"
            nextLink="/testimonials"
            nextText="Testimonials"
          />
        </main>
        <Footer />
      </div>
    </>
  );
};

export default Projects;
