import { useMemo, useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import GalleryFilters from "./gallery/GalleryFilters";
import GalleryGrid from "./gallery/GalleryGrid";
import GalleryLightbox from "./gallery/GalleryLightbox";
import { GALLERY, GalleryItem } from "@/data/gallery";

const Gallery = () => {
  const [category, setCategory] = useState<string>("All");
  const [q, setQ] = useState<string>("");
  const [sort, setSort] = useState<string>("new");
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [open, setOpen] = useState<boolean>(false);
  const [activeIndex, setActiveIndex] = useState<number>(0);
  const [likes, setLikes] = useState<Record<string, number>>({});
  const [liked, setLiked] = useState<Record<string, boolean>>({});
  const [comments, setComments] = useState<Record<string, { id: string; text: string; date: string }[]>>({});
  const [searchParams, setSearchParams] = useSearchParams();

  useEffect(() => {
    const cat = searchParams.get("cat");
    const query = searchParams.get("q");
    if (cat) setCategory(cat);
    if (query) setQ(query);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const next = new URLSearchParams(searchParams);
    if (category && category !== "All") next.set("cat", category); else next.delete("cat");
    if (q && q.trim()) next.set("q", q.trim()); else next.delete("q");
    setSearchParams(next, { replace: true });
  }, [category, q, setSearchParams]);

  const allTags = useMemo(() => GALLERY.flatMap((g) => g.tags), []);

  const filtered: GalleryItem[] = useMemo(() => {
    let items = GALLERY;
    if (category !== "All") items = items.filter((i) => i.category === category);
    if (selectedTags.length) items = items.filter((i) => selectedTags.every((t) => i.tags.includes(t)));
    if (q.trim()) {
      const s = q.toLowerCase();
      items = items.filter((i) => `${i.title} ${i.location ?? ""} ${i.tags.join(" ")}`.toLowerCase().includes(s));
    }
    if (sort === "new") items = [...items].sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));
    if (sort === "old") items = [...items].sort((a, b) => (a.date ?? "").localeCompare(b.date ?? ""));
    if (sort === "liked") items = [...items].sort((a, b) => (b.likes ?? 0) - (a.likes ?? 0));
    return items;
  }, [category, q, sort, selectedTags]);

  const clearAll = () => {
    setCategory("All");
    setQ("");
    setSort("new");
    setSelectedTags([]);
  };

  const toggleTag = (t: string) => {
    setSelectedTags((prev) => (prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t]));
  };

  const openAt = (index: number) => {
    setActiveIndex(index);
    setOpen(true);
  };

  const prev = () => setActiveIndex((i) => (i - 1 + filtered.length) % filtered.length);
  const next = () => setActiveIndex((i) => (i + 1) % filtered.length);

  const active = filtered[activeIndex];
  const likeActive = () => {
    if (!active) return;
    setLiked((m) => ({ ...m, [active.id]: !m[active.id] }));
    setLikes((m) => ({ ...m, [active.id]: (m[active.id] ?? active.likes ?? 0) + (liked[active.id] ? -1 : 1) }));
  };
  const addComment = (text: string) => {
    if (!active) return;
    setComments((m) => ({
      ...m,
      [active.id]: [...(m[active.id] ?? []), { id: Math.random().toString(36).slice(2), text, date: new Date().toISOString() }],
    }));
  };

  return (
    <section id="gallery" className="py-20 bg-background">
      <div className="container mx-auto px-4 max-w-7xl">
        <div className="sticky top-0 z-30 -mx-4 px-4 backdrop-blur bg-white/70 supports-[backdrop-filter]:bg-white/50 border-b">
          <GalleryFilters
            category={category}
            setCategory={setCategory}
            q={q}
            setQ={setQ}
            sort={sort}
            setSort={setSort}
            tags={selectedTags}
            toggleTag={toggleTag}
            clearAll={clearAll}
            availableTags={allTags}
          />
        </div>

        {filtered.length === 0 ? (
          <div className="flex items-center justify-center py-20">
            <div className="text-center">
              <p className="text-lg font-medium text-foreground">No results</p>
              <button className="mt-2 underline" onClick={clearAll}>View All</button>
            </div>
          </div>
        ) : (
          <div className="mt-8">
            <GalleryGrid items={filtered} onOpen={openAt} />
          </div>
        )}

        {filtered.length > 0 && (
          <GalleryLightbox
            open={open}
            onOpenChange={setOpen}
            src={active?.src ?? ""}
            title={active?.title ?? ""}
            caption={`${active?.category ?? ""}${active?.location ? ` • ${active.location}` : ""}`}
            onPrev={prev}
            onNext={next}
            likeCount={likes[active?.id ?? ""] ?? active?.likes}
            isLiked={!!liked[active?.id ?? ""]}
            onLike={likeActive}
            share={() => {
              const url = window.location.href.split("?")[0] + `?id=${active?.id}`;
              if (navigator.share) navigator.share({ title: active?.title, url }).catch(() => {});
              else navigator.clipboard.writeText(url);
            }}
            comments={comments[active?.id ?? ""] ?? []}
            onAddComment={addComment}
          />
        )}
      </div>
    </section>
  );
};

export default Gallery;
